const normalizeStep = (step) => {
    if (
        step === "bahan_pangan" ||
        step === "bahan-pangan" ||
        step === "formula_makanan" ||
        step === "formula-makanan" ||
        step === "formula_gizi" ||
        step === "formula-gizi" ||
        step === "formula" ||
        step === "pre_order"
    )
        return "bahan_pangan";
    if (
        step === "catatan" ||
        step === "catatan_resep" ||
        step === "catatan-resep" ||
        step === "catatan_tim" ||
        step === "catatan-tim" ||
        step === "catatan_kerja" ||
        step === "catatan-kerja"
    )
        return "catatan_resep";
    if (
        step === "order" ||
        step === "review" ||
        step === "review_pengajuan" ||
        step === "pembelian_bahan" ||
        step === "pembelian-bahan"
    )
        return "order";
    return "work_order";
};

const buatMenuSubTab = ref(normalizeStep(props.initialStep));

watch(
    () => props.initialStep,
    (step) => {
        if (step) buatMenuSubTab.value = normalizeStep(step);
    },
);

