// Resep Bahan Baku Baku Terpilih dari Database Resmi Kemenkes (Default Kosong dari 0)
const selectedBahanList = ref([]);

// Resep Bahan Pengganti / Substitusi untuk Varian Alergi (misal: Alergi Telur)
const varianAlergiTelurBahan = computed(() => {
    if (selectedBahanList.value.length === 0) return [];
    return selectedBahanList.value.filter((b) => b.alergen !== "Telur");
});

// Database Master TKPI Aktif (NutriSurvey Indo .fta / Kemenkes .csv / FatSecret)
const extraFatsecretItems = ref([]);

function mergeFatsecretItems(newItems) {
    if (!Array.isArray(newItems)) return;
    const existingIds = new Set([
        ...(props.tkpiDatasets?.fatsecret || []).map((x) => x.id),
        ...extraFatsecretItems.value.map((x) => x.id),
    ]);
    const toAdd = newItems.filter(
        (it) => it && it.id && !existingIds.has(it.id),
    );
    if (toAdd.length > 0) {
        extraFatsecretItems.value = [...extraFatsecretItems.value, ...toAdd];
    }
}

const tkpiItems = computed(() => {
    if (props.selectedSource === "fatsecret") {
        const base = props.tkpiDatasets?.fatsecret || props.tkpiList || [];
        return [...base, ...extraFatsecretItems.value];
    }
    if (
        props.tkpiDatasets &&
        props.tkpiDatasets[props.selectedSource] &&
        props.tkpiDatasets[props.selectedSource].length > 0
    ) {
        return props.tkpiDatasets[props.selectedSource];
    }
    return props.tkpiList || [];
});

// Helper Satuan & Format Unit MBG
function getPortionUnit(satuan = "Kg") {
    const s = (satuan || "Kg").toLowerCase().trim();
    if (s === "kg" || s === "gram" || s === "g") return "g";
    if (s === "liter" || s === "l" || s === "ml") return "mL";
    return satuan || "Kg";
}

// Fungsi Kalkulasi MBG Berdasarkan Satuan
function calculateGrossWeightKg(
    netGram,
    totalPortions,
    bddPercent,
    bufferPercent,
    satuan = "Kg",
) {
    if (!netGram || !totalPortions || !bddPercent || bddPercent <= 0) return 0;
    const bddFactor = (bddPercent || 100) / 100;
    const bufferFactor = 1 + (bufferPercent || 0) / 100;
    const grossPerPortion = (netGram / bddFactor) * bufferFactor;
    const s = (satuan || "Kg").toLowerCase().trim();

    if (s === "kg" || s === "liter" || s === "l") {
        return (grossPerPortion * totalPortions) / 1000;
    }
    return grossPerPortion * totalPortions;
}

function formatGrossWeight(kg, satuan = "Kg") {
    return formatGrossQty(kg, satuan);
}

function formatPortionValue(val, satuan = "Kg") {
    const unit = getPortionUnit(satuan);
    if (val === null || val === undefined || val === "" || isNaN(Number(val)))
        return `0 ${unit}`;
    const num = Number(val);
    if (num <= 0) return `0 ${unit}`;
    return `${parseFloat(num.toFixed(1))} ${unit}`;
}

function formatGram(gram, satuan = "Kg") {
    return formatPortionValue(gram, satuan);
}

function calculateNutritionFromNetGram(
    itemTkpi,
    netGram,
    jenis = "bahan_baku",
) {
    if (jenis === "operasional" || !itemTkpi || !netGram) {
        return { energi: 0, protein: 0, lemak: 0, karbohidrat: 0, serat: 0 };
    }
    const factor = netGram / 100;
    return {
        energi: Number(((itemTkpi.energi || 0) * factor).toFixed(1)),
        protein: Number(((itemTkpi.protein || 0) * factor).toFixed(1)),
        lemak: Number(((itemTkpi.lemak || 0) * factor).toFixed(1)),
        karbohidrat: Number(((itemTkpi.karbohidrat || 0) * factor).toFixed(1)),
        serat: Number(((itemTkpi.serat || 0) * factor).toFixed(1)),
    };
}

function calculateItemFoodCostPerPortion(
    netGram,
    bddPercent,
    bufferPercent,
    hargaPerSatuan,
    satuan = "Kg",
    jenis = "bahan_baku",
) {
    if (
        jenis === "operasional" ||
        !netGram ||
        !hargaPerSatuan ||
        !bddPercent ||
        bddPercent <= 0
    )
        return 0;
    const bddFactor = (bddPercent || 100) / 100;
    const bufferFactor = 1 + (bufferPercent || 0) / 100;
    const grossPerPortion = (netGram / bddFactor) * bufferFactor;
    const s = (satuan || "Kg").toLowerCase().trim();

    if (s === "kg" || s === "liter" || s === "l") {
        const cost = (grossPerPortion / 1000) * hargaPerSatuan;
        return Number(cost) || 0;
    }
    const cost = grossPerPortion * hargaPerSatuan;
    return Number(cost) || 0;
}

