        satuan: "Kg",
        harga_master: null,
        energi: null,
        protein: null,
        lemak: null,
        karbohidrat: null,
        serat: null,
    };
    showManualBahanModal.value = true;
    activeComboboxBlockId.value = null;
}

function saveManualBahan() {
    manualBahanErrors.value = {};
    if (!manualBahanForm.value.nama || !manualBahanForm.value.nama.trim()) {
        manualBahanErrors.value.nama = "Nama bahan baku wajib diisi.";
    }
    if (
        !manualBahanForm.value.nama_po ||
        !manualBahanForm.value.nama_po.trim()
    ) {
        manualBahanErrors.value.nama_po = "Nama di PO wajib diisi.";
    }
    if (!manualBahanForm.value.kategori) {
        manualBahanErrors.value.kategori = "Kategori wajib dipilih.";
    }
    if (!manualBahanForm.value.satuan) {
        manualBahanErrors.value.satuan = "Satuan wajib dipilih.";
    }
    if (
        manualBahanForm.value.harga_master === null ||
        manualBahanForm.value.harga_master === "" ||
        manualBahanForm.value.harga_master === undefined
    ) {
        manualBahanErrors.value.harga_master = "Harga per satuan wajib diisi.";
    } else if (Number(manualBahanForm.value.harga_master) < 0) {
        manualBahanErrors.value.harga_master =
            "Harga tidak boleh bernilai negatif.";
    }

    // Validasi Wajib Kandungan Gizi (Hanya jika Jenis = Bahan Baku)
    const isBahanBaku =
        (manualBahanForm.value.jenis || "bahan_baku") === "bahan_baku";
    if (isBahanBaku) {
        const giziList = [
            { key: "energi", label: "Energi" },
            { key: "protein", label: "Protein" },
            { key: "lemak", label: "Lemak" },
            { key: "karbohidrat", label: "Karbohidrat" },
            { key: "serat", label: "Serat" },
        ];
        giziList.forEach((g) => {
            const val = manualBahanForm.value[g.key];
            if (
                val === null ||
                val === undefined ||
                val === "" ||
                isNaN(Number(val))
            ) {
                manualBahanErrors.value[g.key] =
                    `${g.label} wajib diisi (minimal 0).`;
            } else if (Number(val) < 0) {
                manualBahanErrors.value[g.key] =
                    `${g.label} tidak boleh bernilai negatif.`;
            }
        });
    }

    if (Object.keys(manualBahanErrors.value).length > 0) {
        return;
    }

    const block = manualBahanTargetBlock.value;
    if (!block) return;

    const customId =
        "custom_" + Date.now() + "_" + Math.random().toString(36).substr(2, 5);
    const isOperasionalItem =
        (manualBahanForm.value.jenis || "bahan_baku") === "operasional";
    const energiNum = isOperasionalItem
        ? 0
        : Number(manualBahanForm.value.energi) || 0;
    const proteinNum = isOperasionalItem
        ? 0
        : Number(manualBahanForm.value.protein) || 0;
    const lemakNum = isOperasionalItem
        ? 0
        : Number(manualBahanForm.value.lemak) || 0;
    const karbohidratNum = isOperasionalItem
        ? 0
        : Number(manualBahanForm.value.karbohidrat) || 0;
    const seratNum = isOperasionalItem
        ? 0
        : Number(manualBahanForm.value.serat) || 0;

    const customItem = {
        id: customId,
        code: customId,
        tkpi_id: customId,
        sub_menu_block_id: block.id,
        sub_menu_key: block.subKey,
        nama_sub_menu: block.namaMenu,
        jenis: manualBahanForm.value.jenis || "bahan_baku",
        kategori: manualBahanForm.value.kategori || "Lainnya",
        satuan: manualBahanForm.value.satuan || "Kg",
        nama: manualBahanForm.value.nama.trim(),
        nama_po: manualBahanForm.value.nama_po
            ? manualBahanForm.value.nama_po.trim()
            : manualBahanForm.value.nama.trim(),
        tipe_porsi: block.isAlergi ? "alergi" : "normal",
        jenis_alergi: block.isAlergi ? block.jenisAlergi || "" : "",
        gram_pk: 0,
        gram_pb: 0,
        bdd: 100,
        buffer: 0,
        harga_master:
            manualBahanForm.value.harga_master !== null &&
            manualBahanForm.value.harga_master !== ""
                ? Number(manualBahanForm.value.harga_master)
                : null,
        harga_aktual:
            manualBahanForm.value.harga_master !== null &&
            manualBahanForm.value.harga_master !== ""
                ? Number(manualBahanForm.value.harga_master)
                : null,
        alergen: "",
        keterangan: "-",
        is_custom: true,
        energi: energiNum,
        protein: proteinNum,
        lemak: lemakNum,
        karbohidrat: karbohidratNum,
        serat: seratNum,
        tkpi: {
            id: customId,
            nama: manualBahanForm.value.nama.trim(),
            kategori: manualBahanForm.value.kategori || "Lainnya",
            satuan: manualBahanForm.value.satuan || "Kg",
            bdd: 100,
            energi: energiNum,
            protein: proteinNum,
            lemak: lemakNum,
            karbohidrat: karbohidratNum,
            serat: seratNum,
        },
    };

    selectedBahanList.value.push(customItem);
    showManualBahanModal.value = false;
    manualBahanTargetBlock.value = null;
    if (validationErrors.value.selectedBahan) {
        delete validationErrors.value.selectedBahan;
    }
}

// Navigasi & Highlight Baris Bahan Pangan dari Tabel Rekapitulasi
function scrollToSubMenuBahan(item) {
    if (!item) return;

    if (buatMenuSubTab.value !== "bahan_pangan") {
        buatMenuSubTab.value = "bahan_pangan";
        scrollToTopSection();
    }

    nextTick(() => {
        const targetRowId = `row-bahan-${item.originalIndex}`;
        const targetBlockId = item.sub_menu_block_id
            ? `card-block-${item.sub_menu_block_id}`
            : null;

        let el = document.getElementById(targetRowId);
        if (!el && targetBlockId) {
            el = document.getElementById(targetBlockId);
        }

        if (el) {
            el.scrollIntoView({ behavior: "smooth", block: "center" });
            el.classList.add(
                "ring-4",
                "ring-primary",
                "bg-amber-100/70",
                "transition-all",
                "duration-500",
            );
            const inputPo = el.querySelector('input[type="text"]');
            if (inputPo) {
                inputPo.focus();
            }
            setTimeout(() => {
                el.classList.remove(
                    "ring-4",
                    "ring-primary",
                    "bg-amber-100/70",
                );
            }, 2500);
        }
    });
}

// Opsi Alergi yang tersedia di data Penerima Manfaat untuk dropdown Peruntukan Porsi
const availableAlergiPmOptions = computed(() => {
    const list =
        rekapAlergiDetailPm.value.length > 0
            ? rekapAlergiDetailPm.value
            : rekapAlergiMasterPm.value;

    const options = [];
    const addedSet = new Set();

    // Hanya masukkan alergi yang benar-benar ada PM pada data Penerima Manfaat (total > 0)
    list.forEach((a) => {
        const total = Number(a.total || 0);
        if (a.jenis_alergi && total > 0 && !addedSet.has(a.jenis_alergi)) {
            addedSet.add(a.jenis_alergi);
            options.push({
                jenis_alergi: a.jenis_alergi,
                total: total,
                pk: Number(a.porsi_kecil || 0),
                pb: Number(a.porsi_besar || 0),
                hasPm: true,
            });
        }
    });

    // Pertahankan alergi yang sudah terpilih pada bahan yang sedang diedit (agar tidak hilang)
    selectedBahanList.value.forEach((b) => {
        if (
            b.tipe_porsi === "alergi" &&
            b.jenis_alergi &&
            !addedSet.has(b.jenis_alergi)
        ) {
            addedSet.add(b.jenis_alergi);
            options.push({
                jenis_alergi: b.jenis_alergi,
                total: b.totalTargetCount || 0,
                pk: b.targetPKCount || 0,
                pb: b.targetPBCount || 0,
                hasPm: (b.totalTargetCount || 0) > 0,
            });
        }
    });

    return options;
});

function getPeruntukanPorsiValue(bahan) {
    if (!bahan) return "normal";
    if (bahan.tipe_porsi === "alergi") {
        return `alergi:${bahan.jenis_alergi || ""}`;
    }
    return "normal";
}

function handlePeruntukanPorsiChange(originalIndex, eventVal) {
    const b = selectedBahanList.value[originalIndex];
    if (!b) return;
    if (eventVal === "normal") {
        b.tipe_porsi = "normal";
        b.jenis_alergi = "";
    } else if (eventVal && eventVal.startsWith("alergi:")) {
        b.tipe_porsi = "alergi";
        b.jenis_alergi = eventVal.replace("alergi:", "");
    }
}

// Handler perubahan satuan bahan dalam tabel dengan konversi harga otomatis
function handleRowSatuanChange(
    originalIndex,
    newSatuan,
    oldSatuanOverride = null,
) {
    const item = selectedBahanList.value[originalIndex];
    if (!item) return;
    const oldSatuan = (oldSatuanOverride || item.satuan || "Kg").trim();
    const oldS = oldSatuan.toLowerCase();
    const newS = (newSatuan || "Kg").toLowerCase().trim();

    if (oldS === newS) {
        item.satuan = normalizeSatuan(newSatuan);
        return;
    }

    // Konversi Harga Master & Harga Aktual
    if (
        item.harga_master !== null &&
        item.harga_master !== undefined &&
        item.harga_master !== ""
    ) {
        const hMaster = Number(item.harga_master) || 0;
        const hAktual =
            item.harga_aktual !== null &&
            item.harga_aktual !== undefined &&
            item.harga_aktual !== ""
                ? Number(item.harga_aktual) || 0
                : hMaster;

        // Kg <-> Gram (1 Kg = 1000 Gram)
        if (
            (oldS === "kg" || oldS === "kilogram") &&
            (newS === "gram" || newS === "g")
        ) {
            item.harga_master = Math.max(1, Math.round(hMaster / 1000));
            item.harga_aktual = Math.max(1, Math.round(hAktual / 1000));
        } else if (
            (oldS === "gram" || oldS === "g") &&
            (newS === "kg" || newS === "kilogram")
        ) {
            item.harga_master = Math.round(hMaster * 1000);
            item.harga_aktual = Math.round(hAktual * 1000);
        }
        // Liter <-> mL (1 Liter = 1000 mL)
        else if ((oldS === "liter" || oldS === "l") && newS === "ml") {
            item.harga_master = Math.max(1, Math.round(hMaster / 1000));
            item.harga_aktual = Math.max(1, Math.round(hAktual / 1000));
        } else if (oldS === "ml" && (newS === "liter" || newS === "l")) {
            item.harga_master = Math.round(hMaster * 1000);
            item.harga_aktual = Math.round(hAktual * 1000);
        }
    }

    item.satuan = normalizeSatuan(newSatuan);
}

// Helper filter bahan calculations untuk satu blok tertentu
function getBahanForBlock(blockId) {
    return bahanCalculations.value.filter((b) => {
        if (b.sub_menu_block_id) {
            return b.sub_menu_block_id === blockId;
        }
        // Fallback backward compatibility: masukkan ke blok normal pertama jika belum ada block_id
        const firstBlock = step2SubMenuBlocks.value[0];
        return firstBlock && firstBlock.id === blockId;
    });
}

// Helper kalkulasi ringkasan subtotal per blok
function getBlockSummary(blockId) {
    const items = getBahanForBlock(blockId);
    const totalNetKg = items.reduce((sum, it) => sum + (it.totalNetKg || 0), 0);
    const totalGrossWeightKg = items.reduce(
        (sum, it) => sum + (it.totalWeightKg || 0),
        0,
    );
    const totalCostMaster = items.reduce(
        (sum, it) => sum + (it.subtotalMaster || 0),
        0,
    );
    const totalCostAktual = items.reduce(
        (sum, it) => sum + (it.subtotalAktual || 0),
        0,
    );
    const groupedList = getGroupedUnitList(items);
    const groupedSummary = formatGroupedUnitSummary(items, " • ");
    const groupedSummaryComma = formatGroupedUnitSummary(items, ", ");
    return {
        count: items.length,
        totalNetKg,
        totalGrossKg: totalGrossWeightKg,
        totalCostMaster,
        totalCostAktual,
        groupedList,
        groupedSummary,
        groupedSummaryComma,
    };
}

// Helper untuk mendapatkan nama teks Sub Menu dari objek bahan
function getSubMenuNameFromBahan(it) {
    const info = getSubMenuLabelForBahan(it);
    return info.label || "Sub Menu";
}

// Helper untuk identifikasi nama Sub Menu asal pada Rekapitulasi Bahan Pangan
function getSubMenuLabelForBahan(it) {
    if (it.sub_menu_block_id) {
        const found = step2SubMenuBlocks.value.find(
            (b) => b.id === it.sub_menu_block_id,
        );
        if (found) {
            return {
                label: found.subLabel,
                namaMenu: found.namaMenu,
                isAlergi: found.isAlergi,
                jenisAlergi: found.jenisAlergi,
                badgeClass: found.isAlergi
                    ? "bg-rose-100 text-rose-800 border-rose-300"
                    : "bg-slate-100 text-slate-800 border-slate-300",
            };
        }
    }
    const keyMap = {
        sub_menu_1: "Sub Menu 1",
        sub_menu_2: "Sub Menu 2",
        sub_menu_3: "Sub Menu 3",
        sub_menu_4: "Sub Menu 4",
        sub_menu_5: "Sub Menu 5",
    };
    const label = keyMap[it.sub_menu_key] || "Sub Menu 1";
    const namaMenu =
        it.nama_sub_menu || subMenuKomponen.value[it.sub_menu_key] || "";
    const isAlergi = it.tipe_porsi === "alergi";
    return {
        label: isAlergi ? `${label} • Alergi` : label,
        namaMenu: namaMenu || "-",
        isAlergi,
        jenisAlergi: it.jenis_alergi || "",
        badgeClass: isAlergi
            ? "bg-rose-100 text-rose-800 border-rose-300"
            : "bg-slate-100 text-slate-800 border-slate-300",
    };
}

function scrollToRekapitulasi() {
    nextTick(() => {
        const el = document.getElementById("tabel-rekapitulasi-bahan-pangan");
        if (el) {
            el.scrollIntoView({ behavior: "smooth", block: "start" });
        }
    });
}

function onGlobalWindowClick(e) {
    activeComboboxBlockId.value = null;
    isComboboxGiziOpen.value = false;
    if (
        showDatePickerPopover.value &&
        datePickerContainerRef.value &&
        !datePickerContainerRef.value.contains(e.target)
    ) {
        showDatePickerPopover.value = false;
    }
}

// =========================================================================
// FITUR PERINGATAN / KONFIRMASI PERUBAHAN BELUM DISIMPAN (DIRTY CHECKING)
// =========================================================================
const isSubmitting = ref(false);
const initialFormSnapshot = ref("");
const isNavigationConfirmed = ref(false);
const showLeaveConfirmModal = ref(false);
const pendingNavigation = ref(null);

function takeFormSnapshot() {
    try {
        return JSON.stringify({
            tgl: tanggalRencana.value || "",
            menu: (namaMenuAktif.value || "").trim(),
            sub: {
                s1: (subMenuKomponen.value?.sub_menu_1 || "").trim(),
                s2: (subMenuKomponen.value?.sub_menu_2 || "").trim(),
                s3: (subMenuKomponen.value?.sub_menu_3 || "").trim(),
                s4: (subMenuKomponen.value?.sub_menu_4 || "").trim(),
                s5: (subMenuKomponen.value?.sub_menu_5 || "").trim(),
            },
            alergi: subMenuAlergi.value || {},
            kelompok: (woKelompokList.value || []).map((k) => ({
                id: k.id,
                status: k.status_menerima !== false,
            })),
            bahan: (selectedBahanList.value || []).map((b) => ({
                id: b.id,
                po: b.nama_po || b.nama,
                pk: Number(b.gram_pk) || 0,
                pb: Number(b.gram_pb) || 0,
                bdd: Number(b.bdd) || 0,
                buf: Number(b.buffer) || 0,
                ha: Number(b.harga_aktual) || 0,
                hm: Number(b.harga_master) || 0,
                tip: b.tipe_porsi || "normal",
                al: b.jenis_alergi || "",
                blk: b.sub_menu_block_id || "",
            })),
            catatan: {
                persiapan: (catatanTim.value?.persiapan || []).map((c) => ({
                    m: c.nama_menu,
                    b: c.bahan_baku,
                    j: c.jumlah,
                    s: c.satuan,
                    wm: c.waktu_mulai,
                    ws: c.waktu_selesai,
                    p: c.perlakuan,
                    k: c.keterangan,
                })),
                pengolahan: (catatanTim.value?.pengolahan || []).map((c) => ({
                    m: c.nama_menu,
                    b: c.bahan_baku,
                    j: c.jumlah,
                    s: c.satuan,
                    wm: c.waktu_mulai,
                    ws: c.waktu_selesai,
                    p: c.perlakuan,
                    k: c.keterangan,
                })),
                pemorsian: (catatanTim.value?.pemorsian || []).map((c) => ({
                    m: c.nama_menu,
                    q: c.kuantitas,
                    wm: c.waktu_mulai,
                    ws: c.waktu_selesai,
                    p: c.perlakuan,
                    k: c.keterangan,
                })),
                global: catatanTim.value?.catatan_global || {},
            },
        });
    } catch (e) {
        return "";
    }
}

const isFormDirty = computed(() => {
    if (isSubmitting.value || isNavigationConfirmed.value) {
        return false;
    }
    if (!initialFormSnapshot.value) {
        return false;
    }
    return takeFormSnapshot() !== initialFormSnapshot.value;
});

let hasHistoryTrap = false;

// Pasang trap history saat form kotor agar tombol browser Back memicu popstate di halaman ini
watch(isFormDirty, (dirty) => {
    if (dirty && !hasHistoryTrap && typeof window !== "undefined") {
        try {
            window.history.pushState({ rancangMenuTrap: true }, document.title, window.location.href);
            hasHistoryTrap = true;
        } catch (e) {}
    } else if (!dirty) {
        hasHistoryTrap = false;
    }
});

function handlePopState(e) {
    if (isSubmitting.value || isNavigationConfirmed.value) {
        return;
    }

    if (isFormDirty.value) {
        // Tahan pengguna tetap di halaman ini dengan mendorong kembali state trap
        try {
            window.history.pushState({ rancangMenuTrap: true }, document.title, window.location.href);
        } catch (err) {}

        pendingNavigation.value = { type: "history_back" };
        showLeaveConfirmModal.value = true;
    }
}

function handleKeyDown(e) {
    if (isSubmitting.value || isNavigationConfirmed.value || !isFormDirty.value) {
        return;
    }

    // 1. Intersep Refresh / Reload via keyboard: F5 atau Ctrl+R / Cmd+R
    const isReloadKey =
        e.key === "F5" ||
        ((e.ctrlKey || e.metaKey) && (e.key === "r" || e.key === "R"));

    if (isReloadKey) {
        e.preventDefault();
        e.stopPropagation();
        pendingNavigation.value = { type: "reload" };
        showLeaveConfirmModal.value = true;
        return;
    }

    // 2. Intersep Shortcut Browser Back via keyboard: Alt + ArrowLeft
    const isBackKey = e.altKey && e.key === "ArrowLeft";
    if (isBackKey) {
        e.preventDefault();
        e.stopPropagation();
        pendingNavigation.value = { type: "history_back" };
        showLeaveConfirmModal.value = true;
        return;
    }
}

function handleBeforeUnload(e) {
    if (isFormDirty.value && !isSubmitting.value && !isNavigationConfirmed.value) {
        pendingNavigation.value = { type: "reload" };
        showLeaveConfirmModal.value = true;
        e.preventDefault();
        e.returnValue = "";
        return "";
    }
}

function handleConfirmLeave() {
    showLeaveConfirmModal.value = false;
    isNavigationConfirmed.value = true;

    if (pendingNavigation.value) {
        const nav = pendingNavigation.value;
        pendingNavigation.value = null;

        if (nav.type === "reload") {
            window.location.reload();
            return;
        }

        if (nav.type === "history_back") {
            if (typeof window !== "undefined" && window.history.length > 2) {
                window.history.go(-2);
            } else {
                router.visit("/gizi/daftar-menu");
            }
            return;
        }

        if (nav.url) {
            router.visit(nav.url, {
                method: nav.method || "get",
                data: nav.data || {},
                replace: nav.replace || false,
                preserveScroll: nav.preserveScroll || false,
                preserveState: nav.preserveState || false,
            });
            return;
        }
    }

    router.visit("/gizi/daftar-menu");
}

function handleCancelLeave() {
    showLeaveConfirmModal.value = false;
    pendingNavigation.value = null;
}

function handleNavigasiKembali() {
    if (isFormDirty.value) {
        pendingNavigation.value = { url: "/gizi/daftar-menu", method: "get" };
        showLeaveConfirmModal.value = true;
    } else {
        router.visit("/gizi/daftar-menu");
    }
}

let removeRouterBeforeHook = null;

onMounted(() => {
    window.addEventListener("click", onGlobalWindowClick);
    window.addEventListener("beforeunload", handleBeforeUnload);
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("popstate", handlePopState);

    // Tangkap navigasi keluar dari halaman Rancang Menu via Inertia (sidebar, link, browser back)
    removeRouterBeforeHook = router.on("before", (event) => {
        if (isSubmitting.value || isNavigationConfirmed.value) {
            return;
        }

        if (isFormDirty.value) {
            event.preventDefault();
            pendingNavigation.value = {
                url: event.detail.visit.url,
                method: event.detail.visit.method,
                data: event.detail.visit.data,
                replace: event.detail.visit.replace,
                preserveScroll: event.detail.visit.preserveScroll,
                preserveState: event.detail.visit.preserveState,
            };
            showLeaveConfirmModal.value = true;
        }
    });

    nextTick(() => {
        if (!initialFormSnapshot.value) {
            initialFormSnapshot.value = takeFormSnapshot();
        }
    });
});

onUnmounted(() => {
    window.removeEventListener("click", onGlobalWindowClick);
    window.removeEventListener("beforeunload", handleBeforeUnload);
    window.removeEventListener("keydown", handleKeyDown);
    window.removeEventListener("popstate", handlePopState);
    if (typeof removeRouterBeforeHook === "function") {
        removeRouterBeforeHook();
    }
});

const validationErrors = ref({});

function clearError(field) {
    if (validationErrors.value[field]) {
        delete validationErrors.value[field];
    }
}

// Helper konversi otomatis tombol koma (,) menjadi titik (.) pada input desimal
function handleDecimalKeydown(event) {
    if (event.key === "," || event.key === "Decimal") {
        event.preventDefault();
        const input = event.target;
        const start = input.selectionStart || 0;
        const end = input.selectionEnd || 0;
        const val = input.value || "";
        if (!val.includes(".")) {
            input.value = val.substring(0, start) + "." + val.substring(end);
            input.setSelectionRange(start + 1, start + 1);
            input.dispatchEvent(new Event("input", { bubbles: true }));
        }
    }
}

function handleGramPkInput(originalIndex) {
    if (selectedBahanList.value[originalIndex]) {
        if (
            selectedBahanList.value[originalIndex].gram_pk !== null &&
            selectedBahanList.value[originalIndex].gram_pk !== "" &&
            Number(selectedBahanList.value[originalIndex].gram_pk) < 0
        ) {
            selectedBahanList.value[originalIndex].gram_pk = 0;
        }
    }
    clearError("bahan_" + originalIndex + "_gram");
}

function handleGramPbInput(originalIndex) {
    if (selectedBahanList.value[originalIndex]) {
        if (
            selectedBahanList.value[originalIndex].gram_pb !== null &&
            selectedBahanList.value[originalIndex].gram_pb !== "" &&
            Number(selectedBahanList.value[originalIndex].gram_pb) < 0
        ) {
            selectedBahanList.value[originalIndex].gram_pb = 0;
        }
    }
    clearError("bahan_" + originalIndex + "_gram");
}

function handleBufferInput(originalIndex) {
    if (selectedBahanList.value[originalIndex]) {
        if (
            selectedBahanList.value[originalIndex].buffer !== null &&
            selectedBahanList.value[originalIndex].buffer !== "" &&
            Number(selectedBahanList.value[originalIndex].buffer) < 0
        ) {
            selectedBahanList.value[originalIndex].buffer = 0;
        }
    }
    clearError("bahan_" + originalIndex + "_buffer");
}

function scrollToTopSection() {
    nextTick(() => {
        const topEl =
            document.getElementById("rancang-menu-top-anchor") ||
            document.getElementById("gizi-rancang-menu-container");
        if (topEl) {
            topEl.scrollIntoView({ behavior: "smooth", block: "start" });
        }

        const scrollableContainers =
            document.querySelectorAll(".overflow-y-auto");
        scrollableContainers.forEach((el) => {
            el.scrollTo({ top: 0, behavior: "smooth" });
        });

        window.scrollTo({ top: 0, behavior: "smooth" });
        if (document.documentElement) {
            document.documentElement.scrollTo({ top: 0, behavior: "smooth" });
        }
        if (document.body) {
            document.body.scrollTo({ top: 0, behavior: "smooth" });
        }
    });
}

watch(buatMenuSubTab, (newVal, oldVal) => {
    if (newVal !== oldVal) {
        scrollToTopSection();
        if (newVal === "catatan_resep") {
            const hasPersiapan =
                catatanTim.value?.persiapan &&
                catatanTim.value.persiapan.length > 0;
            const hasPengolahan =
                catatanTim.value?.pengolahan &&
                catatanTim.value.pengolahan.length > 0;
            const hasPemorsian =
                catatanTim.value?.pemorsian &&
                catatanTim.value.pemorsian.length > 0;
            if (!hasPersiapan && !hasPengolahan && !hasPemorsian) {
                generateOtomatisCatatanTim(false);
            } else if (hasPemorsian) {
                // Sinkronisasi target porsi agar alergi hanya muncul di menu yang berkaitan/kena dampak saja
                catatanTim.value.pemorsian.forEach((pRow) => {
                    const matchedMenu = menuOptionsList.value.find(
                        (m) =>
                            (m.name || "").trim().toLowerCase() === (pRow.nama_menu || "").trim().toLowerCase() ||
                            (m.label || "").trim().toLowerCase() === (pRow.nama_menu || "").trim().toLowerCase(),
                    );
                    if (matchedMenu) {
                        pRow.isAlergi = matchedMenu.isAlergi || false;
                        pRow.jenis_alergi = matchedMenu.jenis_alergi || "";
                        pRow.kuantitas = getPemorsianTargetPorsi(matchedMenu);
                    } else {
                        pRow.kuantitas = getPemorsianTargetPorsi(pRow);
                    }
                });
            }
        }
    }
});

function scrollToFirstError() {
    nextTick(() => {
        // Cari elemen dengan indikator error pertama
        const firstErrorEl = document.querySelector(
            ".border-rose-400, .border-rose-500, [data-error-target], .bg-rose-50\\/20, #error-kelompok-target",
        );
        if (firstErrorEl) {
            firstErrorEl.scrollIntoView({
                behavior: "smooth",
                block: "center",
            });
            // Fokuskan jika elemen atau child merupakan field input
            if (
                typeof firstErrorEl.focus === "function" &&
                (firstErrorEl.tagName === "INPUT" ||
                    firstErrorEl.tagName === "SELECT" ||
                    firstErrorEl.tagName === "TEXTAREA")
            ) {
                firstErrorEl.focus();
            } else {
                const innerInput = firstErrorEl.querySelector(
                    "input, select, textarea",
                );
                if (innerInput && typeof innerInput.focus === "function") {
                    innerInput.focus();
                }
            }
        }
    });
}

function validateStep1() {
    const errs = {};
    if (!tanggalRencana.value) {
        errs.tanggalRencana = "Tanggal rencana masak & distribusi wajib diisi.";
    } else {
        // Cek duplikasi tanggal (hanya boleh 1 WO per tanggal, termasuk status Draft)
        const duplicateDateWo = getTakenWoInfo(tanggalRencana.value);
        if (duplicateDateWo) {
            errs.tanggalRencana = `Tanggal ${formatTanggalIndo(tanggalRencana.value)} sudah memiliki Work Order: "${duplicateDateWo.nama_menu}" (${duplicateDateWo.nomor_wo} • Status: ${duplicateDateWo.status}). Hanya diperbolehkan 1 Work Order per tanggal (termasuk status Draft).`;
            triggerSubmitError(errs.tanggalRencana);
        }
    }
    if (!namaMenuAktif.value || !namaMenuAktif.value.trim()) {
        errs.namaMenuAktif = "Nama menu wajib diisi.";
    }
    if (
        !subMenuKomponen.value.sub_menu_1 ||
        !subMenuKomponen.value.sub_menu_1.trim()
    ) {
        errs.sub_menu_1 = "Sub Menu 1 wajib diisi.";
    }
    if (
        !subMenuKomponen.value.sub_menu_2 ||
        !subMenuKomponen.value.sub_menu_2.trim()
    ) {
        errs.sub_menu_2 = "Sub Menu 2 wajib diisi.";
    }
    if (
        !subMenuKomponen.value.sub_menu_3 ||
        !subMenuKomponen.value.sub_menu_3.trim()
    ) {
        errs.sub_menu_3 = "Sub Menu 3 wajib diisi.";
    }
    if (
        !subMenuKomponen.value.sub_menu_4 ||
        !subMenuKomponen.value.sub_menu_4.trim()
    ) {
        errs.sub_menu_4 = "Sub Menu 4 wajib diisi.";
    }
    if (
        !subMenuKomponen.value.sub_menu_5 ||
        !subMenuKomponen.value.sub_menu_5.trim()
    ) {
        errs.sub_menu_5 = "Sub Menu 5 wajib diisi.";
    }

    // Validasi menu pengganti alergi (jika ditambahkan, jenis dan nama menu pengganti TIDAK BOLEH KOSONG)
    [
        "sub_menu_1",
        "sub_menu_2",
        "sub_menu_3",
        "sub_menu_4",
        "sub_menu_5",
    ].forEach((subKey, idx) => {
        const list = subMenuAlergi.value[subKey];
        if (Array.isArray(list) && list.length > 0) {
            list.forEach((item, itemIdx) => {
                const subLabel = `Sub Menu ${idx + 1}`;
                if (!item.jenis_alergi || !item.jenis_alergi.trim()) {
                    errs[`alergi_${subKey}_${itemIdx}_jenis`] =
                        `Pilih jenis alergi untuk ${subLabel}.`;
                }
                if (!item.menu_pengganti || !item.menu_pengganti.trim()) {
                    errs[`alergi_${subKey}_${itemIdx}_menu`] =
                        `Menu pengganti ${subLabel} wajib diisi.`;
                }
            });
        }
    });

    if (kelompokMenerimaAktif.value.length === 0) {
        errs.kelompok =
            "Minimal 1 kelompok sasaran penerima manfaat harus berstatus Menerima.";
    } else {
        const zeroReceiving = woKelompokList.value.find(
            (k) =>
                k.status_menerima !== false &&
                (Number(k.total_porsi_kecil) || 0) +
                    (Number(k.total_porsi_besar) || 0) <=
                    0,
        );
        if (zeroReceiving) {
            errs.kelompok = `Kelompok "${zeroReceiving.nama_kelompok}" berstatus Menerima tetapi memiliki 0 porsi. Wajib minimal 1 porsi atau tandai 'Tidak Menerima'.`;
        }
    }
    validationErrors.value = errs;
    const isValid = Object.keys(errs).length === 0;
    if (!isValid) {
        scrollToFirstError();
    }
    return isValid;
}

function validateStep2() {
    const isStep1Valid = validateStep1();
    if (!isStep1Valid) {
        return false;
    }
    const errs = { ...validationErrors.value };

    if (!selectedBahanList.value || selectedBahanList.value.length === 0) {
        nextTick(() => {
            const firstBlock =
                document.getElementById("card-block-sub_menu_1") ||
                document.querySelector("[id^='card-block-']");
            if (firstBlock) {
                firstBlock.scrollIntoView({
                    behavior: "smooth",
                    block: "center",
                });
                firstBlock.classList.add("ring-2", "ring-rose-400");
                setTimeout(() => {
                    firstBlock.classList.remove("ring-2", "ring-rose-400");
                }, 2500);
            }
        });
        return false;
    }

    selectedBahanList.value.forEach((b, i) => {
        if (!b.keterangan || !b.keterangan.trim()) {
            b.keterangan = "-";
        }
        if (!b.nama_po || !b.nama_po.trim()) {
            errs["bahan_" + i + "_nama_po"] = "Nama di PO wajib diisi.";
        }
        if (
            b.tipe_porsi === "alergi" &&
            (!b.jenis_alergi || !b.jenis_alergi.trim())
        ) {
            errs["bahan_" + i + "_alergi"] = "Jenis alergi wajib dipilih.";
        }
        const pkVal = Number(b.gram_pk) || 0;
        const pbVal = Number(b.gram_pb) || 0;
        if (pkVal < 0 || pbVal < 0) {
            errs["bahan_" + i + "_gram"] = "Gramasi tidak boleh kurang dari 0.";
        } else if (pkVal <= 0 && pbVal <= 0) {
            errs["bahan_" + i + "_gram"] =
                "Wajib salah satu dari PK atau PB > 0.";
        }

        const hargaVal = Number(b.harga_master) || 0;
        if (
            b.harga_master === null ||
            b.harga_master === undefined ||
            b.harga_master === "" ||
            hargaVal <= 0
        ) {
            errs["bahan_" + i + "_harga"] = "Harga wajib diisi > 0";
        }

        if (
            b.bdd === null ||
            b.bdd === undefined ||
            b.bdd === "" ||
            Number(b.bdd) <= 0
        ) {
            errs["bahan_" + i + "_bdd"] = "BDD > 0%";
        }
        if (
            b.buffer === null ||
            b.buffer === undefined ||
            b.buffer === "" ||
            Number(b.buffer) < 0
        ) {
            errs["bahan_" + i + "_buffer"] = "Wajib >= 0%";
        }
    });

    validationErrors.value = errs;
    const isValid = Object.keys(errs).length === 0;
    if (!isValid) {
        scrollToFirstError();
    }
    return isValid;
}

function handleSwitchSubTab(targetTab) {
    if (targetTab === "work_order") {
        buatMenuSubTab.value = "work_order";
        scrollToTopSection();
        return;
    }

    // Step 1 WAJIB VALID untuk dapat berpindah ke Step 2 atau Step 3
    if (!validateStep1()) {
        buatMenuSubTab.value = "work_order";
        scrollToTopSection();
        return;
    }

    if (
        targetTab === "bahan_pangan" ||
        targetTab === "pre_order" ||
        targetTab === "formula-gizi" ||
        targetTab === "formula_gizi"
    ) {
        buatMenuSubTab.value = "bahan_pangan";
        scrollToTopSection();
        return;
    }

    if (
        targetTab === "catatan" ||
        targetTab === "catatan_resep" ||
        targetTab === "catatan-resep" ||
        targetTab === "catatan_tim" ||
        targetTab === "catatan-tim" ||
        targetTab === "catatan_kerja" ||
        targetTab === "catatan-kerja"
    ) {
        if (!validateStep2()) {
            buatMenuSubTab.value = "bahan_pangan";
            scrollToTopSection();
            return;
        }
        buatMenuSubTab.value = "catatan_resep";
        scrollToTopSection();
        return;
    }

    if (
        targetTab === "order" ||
        targetTab === "review" ||
        targetTab === "review_pengajuan" ||
        targetTab === "pembelian_bahan" ||
        targetTab === "pembelian-bahan"
    ) {
        if (!validateStep1()) {
            buatMenuSubTab.value = "work_order";
            scrollToTopSection();
            return;
        }
        if (!validateStep2()) {
            buatMenuSubTab.value = "bahan_pangan";
            scrollToTopSection();
            return;
        }
        if (!validateStep3()) {
            buatMenuSubTab.value = "catatan_resep";
            return;
        }
        buatMenuSubTab.value = "order";
        scrollToTopSection();
        return;
    }

    buatMenuSubTab.value = normalizeStep(targetTab);
}

function handleMulaiFormulasiWo() {
    if (!validateStep1()) {
        return;
    }
    buatMenuSubTab.value = "bahan_pangan";
    scrollToTopSection();
}

function handleRemoveBahan(index) {
    selectedBahanList.value.splice(index, 1);
    // Clear error for this index if any
    delete validationErrors.value.selectedBahan;
}

// Arahkan fokus dan scroll langsung ke input yang masih kosong
function focusInvalidField(tim, index, fieldName) {
    activeTimTab.value = tim;
    nextTick(() => {
        const elId = `catatan_${tim}_${index}_${fieldName}`;
        const el = document.getElementById(elId);
        if (el) {
            el.focus();
            el.scrollIntoView({ behavior: "smooth", block: "center" });
            el.classList.add("ring-2", "ring-rose-500", "border-rose-500", "bg-rose-50");
            setTimeout(() => {
                el.classList.remove("ring-2", "ring-rose-500");
            }, 3000);
        }
    });
}

// Berpindah antar tab tim (Persiapan | Pengolahan | Pemorsian) secara bebas
function handleSwitchTimTab(targetTim) {
    activeTimTab.value = targetTim;
}

function validateStep3() {
    const isStep1Valid = validateStep1();
    if (!isStep1Valid) {
        buatMenuSubTab.value = "work_order";
        scrollToTopSection();
        return false;
    }
    const isStep2Valid = validateStep2();
    if (!isStep2Valid) {
        buatMenuSubTab.value = "bahan_pangan";
        scrollToTopSection();
        return false;
    }

    const tims = [
        { key: "persiapan", label: "Tim Persiapan" },
        { key: "pengolahan", label: "Tim Pengolahan" },
        { key: "pemorsian", label: "Tim Pemorsian" },
    ];

    for (const t of tims) {
        const rows = catatanTim.value[t.key] || [];
        if (rows.length === 0) {
            activeTimTab.value = t.key;
            nextTick(() => {
                const addBtn =
                    document.querySelector("button[title*='Tambah Baris Catatan']") ||
                    document.querySelector("#catatan_tambah_baris");
                if (addBtn) {
                    addBtn.scrollIntoView({ behavior: "smooth", block: "center" });
                    addBtn.classList.add("ring-2", "ring-rose-400");
                    setTimeout(() => addBtn.classList.remove("ring-2", "ring-rose-400"), 2500);
                }
            });
            return false;
        }

        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            if (!row.waktu_mulai) {
                focusInvalidField(t.key, i, "waktu_mulai");
                return false;
            }
            if (!row.waktu_selesai) {
                focusInvalidField(t.key, i, "waktu_selesai");
                return false;
            }
            if (!row.perlakuan || !row.perlakuan.trim()) {
                focusInvalidField(t.key, i, "perlakuan");
                return false;
            }
            if (!row.keterangan || !row.keterangan.trim()) {
                focusInvalidField(t.key, i, "keterangan");
                return false;
            }
            if (t.key === "pemorsian" && (!row.kuantitas || !row.kuantitas.trim())) {
                focusInvalidField(t.key, i, "kuantitas");
                return false;
            }
        }
    }

    return true;
}

function handleLanjutStep3() {
    if (!validateStep1()) {
        buatMenuSubTab.value = "work_order";
        scrollToTopSection();
        return;
    }
    if (!validateStep2()) {
        return;
    }
    const hasPersiapan =
        catatanTim.value?.persiapan && catatanTim.value.persiapan.length > 0;
    const hasPengolahan =
        catatanTim.value?.pengolahan && catatanTim.value.pengolahan.length > 0;
    const hasPemorsian =
        catatanTim.value?.pemorsian && catatanTim.value.pemorsian.length > 0;
    if (!hasPersiapan && !hasPengolahan && !hasPemorsian) {
        generateOtomatisCatatanTim(false);
    } else if (catatanTim.value?.pemorsian) {
        // Sinkronisasi target porsi agar alergi hanya muncul di menu yang berkaitan/kena dampak saja
        catatanTim.value.pemorsian.forEach((pRow) => {
            const matchedMenu = menuOptionsList.value.find(
                (m) =>
                    (m.name || "").trim().toLowerCase() === (pRow.nama_menu || "").trim().toLowerCase() ||
                    (m.label || "").trim().toLowerCase() === (pRow.nama_menu || "").trim().toLowerCase(),
            );
            if (matchedMenu) {
                pRow.isAlergi = matchedMenu.isAlergi || false;
                pRow.jenis_alergi = matchedMenu.jenis_alergi || "";
                pRow.kuantitas = getPemorsianTargetPorsi(matchedMenu);
            } else {
                pRow.kuantitas = getPemorsianTargetPorsi(pRow);
            }
        });
    }
    buatMenuSubTab.value = "catatan_resep";
    scrollToTopSection();
}

function handleLanjutStep4() {
    if (!validateStep1()) {
        buatMenuSubTab.value = "work_order";
        scrollToTopSection();
        return;
    }
    if (!validateStep2()) {
        buatMenuSubTab.value = "bahan_pangan";
        scrollToTopSection();
        return;
    }
    if (!validateStep3()) {
        return;
    }
    buatMenuSubTab.value = "order";
    scrollToTopSection();
}

function simpanDraftStep3() {
    if (!validateStep1()) {
        buatMenuSubTab.value = "work_order";
        scrollToTopSection();
        return;
    }
    if (!validateStep2()) {
        buatMenuSubTab.value = "bahan_pangan";
        scrollToTopSection();
        return;
    }
    isSubmitting.value = true;
    statusPengajuanWo.value = "Draft";
    const payload = getPayload("Draft", 3);

    router.post("/gizi/work-order", payload, {
        preserveScroll: true,
        onSuccess: () => {
            isSubmitting.value = false;
            initialFormSnapshot.value = takeFormSnapshot();
            triggerSubmitSuccess(
                "Draft Catatan Kerja Tim Produksi (Langkah 3) berhasil disimpan!",
            );
        },
        onError: () => {
            isSubmitting.value = false;
        },
    });
}

