    persiapan: [],
    pengolahan: [],
    pemorsian: [],
    catatan_global: {
        persiapan: "",
        pengolahan: "",
        pemorsian: "",
    },
});

// Active team tab dalam Langkah 3: 'persiapan' | 'pengolahan' | 'pemorsian'
