                                                        false
                                                            ? 'bg-slate-100 text-slate-400 border-slate-200 opacity-60'
                                                            : 'bg-slate-50 text-slate-700',
                                                    ]"
                                                >
                                                    {{ k.kategori }}
                                                </Badge>
                                            </td>

                                            <!-- Porsi Kecil -->
                                            <td
                                                class="p-3 text-center align-middle font-bold"
                                                :class="
                                                    k.status_menerima === false
                                                        ? 'text-slate-300 line-through font-normal'
                                                        : 'text-slate-800 bg-white'
                                                "
                                            >
                                                {{ k.total_porsi_kecil }}
                                            </td>

                                            <!-- Porsi Besar -->
                                            <td
                                                class="p-3 text-center align-middle font-bold"
                                                :class="
                                                    k.status_menerima === false
                                                        ? 'text-slate-300 line-through font-normal'
                                                        : 'text-indigo-900 bg-indigo-50/20'
                                                "
                                            >
                                                {{ k.total_porsi_besar }}
                                            </td>

                                            <!-- Total PM -->
                                            <td
                                                class="p-3 text-center font-black text-sm align-middle"
                                                :class="
                                                    k.status_menerima === false
                                                        ? 'text-slate-300 line-through font-normal'
                                                        : 'text-slate-900'
                                                "
                                            >
                                                {{ k.total_penerima }}
                                            </td>

                                            <!-- Alergi (Detail Breakdown per Jenis) -->
                                            <td class="p-3 align-middle">
                                                <div
                                                    v-if="
                                                        k.keterangan_alergi &&
                                                        k.keterangan_alergi
                                                            .length > 0
                                                    "
                                                    class="space-y-1"
                                                >
                                                    <div
                                                        v-for="(
                                                            al, alIdx
                                                        ) in k.keterangan_alergi"
                                                        :key="alIdx"
                                                        class="text-[11px] font-bold"
                                                        :class="
                                                            k.status_menerima ===
                                                            false
                                                                ? 'text-slate-300 line-through font-normal'
                                                                : 'text-rose-700'
                                                        "
                                                    >
                                                        ⚠️
                                                        {{ al.jenis_alergi }}:
                                                        <span
                                                            class="font-black text-rose-900 ml-0.5"
                                                            :class="
                                                                k.status_menerima ===
                                                                false
                                                                    ? 'text-slate-300 line-through'
                                                                    : ''
                                                            "
                                                        >
                                                            {{
                                                                (Number(
                                                                    al.porsi_kecil,
                                                                ) || 0) +
                                                                (Number(
                                                                    al.porsi_besar,
                                                                ) || 0)
                                                            }}
                                                        </span>
                                                        <span
                                                            class="text-[10px] text-slate-500 font-normal ml-1"
                                                        >
                                                            (PK:
                                                            {{
                                                                al.porsi_kecil ||
                                                                0
                                                            }}, PB:
                                                            {{
                                                                al.porsi_besar ||
                                                                0
                                                            }})
                                                        </span>
                                                    </div>
                                                </div>
                                                <div
                                                    v-else-if="
                                                        (k.alergi_porsi_kecil ||
                                                            0) +
                                                            (k.alergi_porsi_besar ||
                                                                0) >
                                                        0
                                                    "
                                                    class="text-[11px] font-bold"
                                                    :class="
                                                        k.status_menerima ===
                                                        false
                                                            ? 'text-slate-300 line-through font-normal'
                                                            : 'text-rose-700'
                                                    "
                                                >
                                                    ⚠️
                                                    {{
                                                        (k.alergi_porsi_kecil ||
                                                            0) +
                                                        (k.alergi_porsi_besar ||
                                                            0)
                                                    }}
                                                    Alergi
                                                    <span
                                                        class="block text-[10px] text-slate-500 font-normal"
                                                    >
                                                        PK:
                                                        {{
                                                            k.alergi_porsi_kecil ||
                                                            0
                                                        }}
                                                        • PB:
                                                        {{
                                                            k.alergi_porsi_besar ||
                                                            0
                                                        }}
                                                    </span>
                                                </div>
                                                <div
                                                    v-else
                                                    class="text-[11px] font-medium"
                                                    :class="
                                                        k.status_menerima ===
                                                        false
                                                            ? 'text-slate-300 line-through'
                                                            : 'text-emerald-700'
                                                    "
                                                >
                                                    ✓ Normal
                                                </div>
                                            </td>

                                            <!-- Aksi -->
                                            <td
                                                class="py-3 px-3 text-center align-middle"
                                            >
                                                <div
                                                    class="flex items-center justify-center gap-1.5"
                                                >
                                                    <button
                                                        type="button"
                                                        :disabled="
                                                            k.status_menerima ===
                                                            false
                                                        "
                                                        @click="
                                                            handleOpenModalEditPm(
                                                                k,
                                                            )
                                                        "
                                                        :class="[
                                                            k.status_menerima ===
                                                            false
                                                                ? 'opacity-30 cursor-not-allowed bg-slate-100 text-slate-300 border-slate-200 pointer-events-none'
                                                                : 'bg-amber-50 hover:bg-amber-100 text-amber-600 border-amber-200/80 cursor-pointer shadow-2xs',
                                                            'h-8 w-8 rounded-lg border flex items-center justify-center transition-colors',
                                                        ]"
                                                        :title="
                                                            k.status_menerima ===
                                                            false
                                                                ? 'Kelompok Tidak Menerima (Non-Aktif)'
                                                                : 'Edit Detail PM per Sub-Sub Kategori'
                                                        "
                                                    >
                                                        <Edit3
                                                            class="h-4 w-4"
                                                        />
                                                    </button>

                                                    <button
                                                        v-if="
                                                            k.status_menerima !==
                                                            false
                                                        "
                                                        type="button"
                                                        @click="
                                                            handleToggleStatusMenerima(
                                                                k,
                                                                false,
                                                            )
                                                        "
                                                        class="h-8 w-8 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-600 border border-rose-200/80 flex items-center justify-center shadow-2xs transition-colors cursor-pointer"
                                                        title="Tandai TIDAK MENERIMA Menu Hari Ini"
                                                    >
                                                        <UserX
                                                            class="h-4 w-4"
                                                        />
                                                    </button>
                                                    <button
                                                        v-else
                                                        type="button"
                                                        @click="
                                                            handleToggleStatusMenerima(
                                                                k,
                                                                true,
                                                            )
                                                        "
                                                        class="h-8 w-8 rounded-lg bg-emerald-50 hover:bg-emerald-100 text-emerald-600 border border-emerald-200/80 flex items-center justify-center shadow-2xs transition-colors cursor-pointer"
                                                        title="Aktifkan Kembali Penerimaan"
                                                    >
                                                        <RotateCcw
                                                            class="h-4 w-4"
                                                        />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                        <div
                            v-if="validationErrors.kelompok"
                            class="p-3.5 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 font-bold flex items-center gap-2 mt-3"
                        >
                            <AlertCircle
                                class="h-4 w-4 shrink-0 text-rose-600"
                            />
                            <span>{{ validationErrors.kelompok }}</span>
                        </div>
                    </div>

                    <!-- Bottom Action Button -->
                    <div
                        class="pt-4 border-t border-slate-200 flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3.5"
                    >
                        <div class="text-xs text-slate-500">
                            Pastikan tanggal, nama menu, dan status penerima
                            sasaran sudah sesuai sebelum melanjutkan.
                        </div>
                        <div class="flex flex-col sm:flex-row items-stretch sm:items-center gap-2.5 w-full sm:w-auto">
                            <Button
                                type="button"
                                @click="simpanDraftStep1"
                                :disabled="isSubmitting"
                                className="bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 text-xs font-bold px-4 h-11 rounded-xl cursor-pointer w-full sm:w-auto flex items-center justify-center gap-1.5 shadow-2xs"
                            >
                                <FileText class="h-4 w-4" />
                                <span>Simpan Draft (Langkah 1)</span>
                            </Button>
                            <Button
                                type="button"
                                @click="handleMulaiFormulasiWo"
                                className="bg-primary hover:bg-primary/90 text-white text-xs font-black px-6 h-11 flex items-center justify-center gap-2 rounded-xl shadow-xs cursor-pointer w-full sm:w-auto text-center"
                            >
                                <span
                                    >Lanjut ke Formula Makanan (Langkah 2)</span
                                >
                                <ArrowRight class="h-4 w-4 shrink-0" />
                            </Button>
                        </div>
                    </div>
                </CardContent>
            </Card>

            <!-- Modal Edit Detail Penerima Manfaat per Sub-Sub Kategori -->
            <Modal
                :show="showModalEditPm"
                @close="showModalEditPm = false"
                maxWidth="3xl"
            >
                <div class="p-5 sm:p-6 space-y-5">
                    <!-- Modal Header -->
                    <div
                        class="flex items-start justify-between border-b border-slate-100 pb-3"
                    >
                        <div class="flex items-center gap-3">
                            <div
                                class="h-10 w-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center shrink-0"
                            >
                                <School class="h-5 w-5" />
                            </div>
                            <div>
                                <h3 class="text-base font-black text-slate-900">
                                    Edit Rincian PM:
                                    {{ editingKelompok?.nama_kelompok }}
                                </h3>
                                <p class="text-xs text-slate-500 mt-0.5">
                                    Kategori:
                                    <strong class="text-slate-800">{{
                                        editingKelompok?.kategori
                                    }}</strong>
                                    • Wilayah:
                                    {{ editingKelompok?.desa_kelurahan }},
                                    {{ editingKelompok?.kecamatan }}
                                </p>
                            </div>
                        </div>
                        <button
                            type="button"
                            @click="showModalEditPm = false"
                            class="text-slate-400 hover:text-slate-600 p-1.5 rounded-lg hover:bg-slate-100 transition-colors"
                        >
                            <X class="h-5 w-5" />
                        </button>
                    </div>

                    <!-- Modal Body: Tabel Sub-Sub Kategori -->
                    <div class="space-y-4">
                        <div
                            v-if="modalPmError"
                            class="p-3 bg-rose-50 border border-rose-300 rounded-xl text-xs text-rose-800 font-bold flex items-center gap-2"
                        >
                            <AlertCircle
                                class="h-4 w-4 shrink-0 text-rose-600"
                            />
                            <span>{{ modalPmError }}</span>
                        </div>
                        <div class="flex items-center justify-between">
                            <h4
                                class="text-xs font-bold text-slate-700 uppercase tracking-wider"
                            >
                                Rincian Kuota Porsi / Penerima per Jenjang:
                            </h4>
                            <span class="text-xs text-slate-500">
                                Format input: Laki-laki (L) + Perempuan (P)
                            </span>
                        </div>

                        <div
                            class="rounded-xl border border-slate-200 overflow-x-auto max-h-60 overflow-y-auto"
                        >
                            <table
                                class="w-full min-w-[500px] text-left text-xs border-collapse"
                            >
                                <thead
                                    class="bg-slate-50 text-slate-700 font-bold border-b border-slate-200 uppercase text-[10px] sticky top-0 z-10 shadow-2xs"
                                >
                                    <tr>
                                        <th class="p-3">
                                            Sub-Kategori / Jenjang
                                        </th>
                                        <th class="p-3">Peruntukan Porsi</th>
                                        <th
                                            class="p-3 text-center min-w-[100px]"
                                        >
                                            Laki-laki (L)
                                        </th>
                                        <th
                                            class="p-3 text-center min-w-[100px]"
                                        >
                                            Perempuan (P)
                                        </th>
                                        <th class="p-3 text-right">Subtotal</th>
                                    </tr>
                                </thead>
                                <tbody
                                    class="divide-y divide-slate-100 text-slate-800"
                                >
                                    <tr
                                        v-for="(r, rIdx) in editFormRincian"
                                        :key="r.sub_kategori || rIdx"
                                        class="hover:bg-white"
                                    >
                                        <td
                                            class="p-3 font-bold text-slate-900"
                                        >
                                            {{ r.sub_kategori }}
                                        </td>
                                        <td class="p-3">
                                            <Badge
                                                variant="outline"
                                                :class="[
                                                    'font-extrabold text-[10px]',
                                                    r.jenis_porsi ===
                                                    'Porsi Kecil'
                                                        ? 'bg-amber-50 text-slate-700 border-amber-300'
                                                        : 'bg-indigo-50 text-indigo-800 border-indigo-300',
                                                ]"
                                            >
                                                {{ r.jenis_porsi }}
                                            </Badge>
                                        </td>
                                        <td class="p-2 text-center">
                                            <input
                                                type="number"
                                                min="0"
                                                v-model.number="
                                                    r.jumlah_laki_laki
                                                "
                                                class="w-20 text-center text-xs font-bold rounded-lg border-slate-300 p-1.5 focus:ring-primary focus:border-primary"
                                            />
                                        </td>
                                        <td class="p-2 text-center">
                                            <input
                                                type="number"
                                                min="0"
                                                v-model.number="
                                                    r.jumlah_perempuan
                                                "
                                                class="w-20 text-center text-xs font-bold rounded-lg border-slate-300 p-1.5 focus:ring-primary focus:border-primary"
                                            />
                                        </td>
                                        <td
                                            class="p-3 text-right font-black text-slate-900"
                                        >
                                            {{
                                                (Number(r.jumlah_laki_laki) ||
                                                    0) +
                                                (Number(r.jumlah_perempuan) ||
                                                    0)
                                            }}
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>

                        <!-- Input Khusus Kuota Porsi Alergi (Jenis Alergen Bersumber dari Master Data PM) -->
                        <div
                            class="p-4 rounded-xl bg-rose-50/60 border border-rose-200/80 space-y-3"
                        >
                            <div>
                                <h5
                                    class="text-xs font-bold text-rose-900 flex items-center gap-1.5"
                                >
                                    <AlertCircle
                                        class="h-4 w-4 text-rose-600"
                                    />
                                    <span
                                        >Penyesuaian Porsi Khusus Alergi
                                        (Membutuhkan Menu Substitusi)</span
                                    >
                                </h5>
                                <p class="text-[11px] text-rose-700 mt-0.5">
                                    Daftar jenis alergen bersumber dari master
                                    data
                                    <strong>Penerima Manfaat</strong>. Anda
                                    dapat menyesuaikan jumlah kuota porsi (PK /
                                    PB) untuk Work Order ini jika ada perubahan
                                    kehadiran.
                                </p>
                            </div>

                            <!-- Tabel Daftar Alergi Terdaftar -->
                            <div
                                v-if="editFormKeteranganAlergi.length > 0"
                                class="rounded-lg border border-rose-200 bg-white overflow-x-auto"
                            >
                                <table
                                    class="w-full min-w-[500px] text-left text-xs border-collapse"
                                >
                                    <thead
                                        class="bg-rose-100/60 text-rose-900 font-bold border-b border-rose-200 uppercase text-[10px]"
                                    >
                                        <tr>
                                            <th class="p-3">
                                                Jenis Alergen (Master PM)
                                            </th>
                                            <th
                                                class="p-3 text-center min-w-[110px]"
                                            >
                                                Porsi Kecil (PK)
                                            </th>
                                            <th
                                                class="p-3 text-center min-w-[110px]"
                                            >
                                                Porsi Besar (PB)
                                            </th>
                                            <th class="p-3 text-right">
                                                Subtotal Alergi
                                            </th>
                                        </tr>
                                    </thead>
                                    <tbody
                                        class="divide-y divide-rose-100 text-slate-800"
                                    >
                                        <tr
                                            v-for="(
                                                alItem, alIdx
                                            ) in editFormKeteranganAlergi"
                                            :key="alIdx"
                                            class="hover:bg-white"
                                        >
                                            <td
                                                class="p-3 font-bold text-slate-900 align-middle"
                                            >
                                                <div
                                                    class="flex items-center gap-2"
                                                >
                                                    <span
                                                        class="h-2 w-2 rounded-full bg-rose-500 shrink-0"
                                                    ></span>
                                                    <span
                                                        class="text-xs font-black text-rose-950"
                                                        >{{
                                                            alItem.jenis_alergi
                                                        }}</span
                                                    >
                                                </div>
                                            </td>
                                            <td
                                                class="p-2 text-center align-middle"
                                            >
                                                <input
                                                    type="number"
                                                    min="0"
                                                    :max="modalTotalPk"
                                                    v-model.number="
                                                        alItem.porsi_kecil
                                                    "
                                                    class="w-20 text-center text-xs font-bold rounded-lg border-rose-300 bg-white p-1.5 focus:ring-rose-400 focus:border-rose-400"
                                                />
                                            </td>
                                            <td
                                                class="p-2 text-center align-middle"
                                            >
                                                <input
                                                    type="number"
                                                    min="0"
                                                    :max="modalTotalPb"
                                                    v-model.number="
                                                        alItem.porsi_besar
                                                    "
                                                    class="w-20 text-center text-xs font-bold rounded-lg border-rose-300 bg-white p-1.5 focus:ring-rose-400 focus:border-rose-400"
                                                />
                                            </td>
                                            <td
                                                class="p-3 text-right font-black text-rose-900 text-xs align-middle"
                                            >
                                                {{
                                                    (Number(
                                                        alItem.porsi_kecil,
                                                    ) || 0) +
                                                    (Number(
                                                        alItem.porsi_besar,
                                                    ) || 0)
                                                }}
                                                PM
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>

                            <div
                                v-else
                                class="p-4 text-center text-slate-500 text-xs bg-white rounded-xl border border-dashed border-rose-200 space-y-1"
                            >
                                <p class="font-bold text-slate-700">
                                    Tidak ada riwayat alergi yang terdaftar
                                    untuk kelompok sasaran ini.
                                </p>
                                <p class="text-[11px] text-slate-500">
                                    Penambahan atau pengelolaan jenis alergen
                                    dilakukan melalui master data
                                    <strong class="text-slate-800"
                                        >Penerima Manfaat</strong
                                    >.
                                </p>
                            </div>
                        </div>

                        <!-- Live Summary Bar -->
                        <div
                            class="p-3.5 rounded-xl bg-slate-900 text-white flex flex-wrap items-center justify-between gap-3 text-xs"
                        >
                            <div>
                                <span class="text-slate-400"
                                    >Hasil Rekapitulasi:
                                </span>
                                <strong class="text-white ml-1"
                                    >Total {{ modalTotalPm }} PM</strong
                                >
                            </div>
                            <div class="flex items-center gap-3">
                                <span class="text-amber-300 font-bold"
                                    >PK: {{ modalTotalPk }} Porsi</span
                                >
                                <span class="text-indigo-300 font-bold"
                                    >PB: {{ modalTotalPb }} Porsi</span
                                >
                                <span class="text-rose-300 font-bold"
                                    >Alergi: {{ modalGrandTotalAlergi }} Porsi
                                    (PK: {{ modalTotalAlergiPk }}, PB:
                                    {{ modalTotalAlergiPb }})</span
                                >
                            </div>
                        </div>
                    </div>

                    <!-- Modal Footer -->
                    <div
                        class="flex items-center justify-end gap-3 pt-3 border-t border-slate-100"
                    >
                        <Button
                            type="button"
                            variant="outline"
                            @click="showModalEditPm = false"
                            className="text-xs font-bold cursor-pointer"
                        >
                            Batal
                        </Button>
                        <Button
                            type="button"
                            @click="handleSimpanEditDetailPm"
                            className="bg-primary hover:bg-primary/90 text-white text-xs font-bold flex items-center gap-1.5 cursor-pointer shadow-xs"
                        >
                            <Check class="h-4 w-4" />
                            <span>Simpan Perubahan</span>
                        </Button>
                    </div>
                </div>
            </Modal>
        </div>

        <!-- ========================================================================================= -->

        <!-- ========================================================================================= -->
        <!-- Bagian 2: Bahan Pangan & Estimasi Biaya Belanja (Step 2) -->
        <!-- ========================================================================================= -->
        <div v-if="buatMenuSubTab === 'bahan_pangan'" class="space-y-6">
            <!-- Header Bahan Pangan Card -->
            <Card className="bg-white border-slate-200 shadow-xs">
                <CardHeader
                    className="p-4 sm:p-5 border-b border-slate-100 bg-white"
                >
                    <div
                        class="flex flex-col md:flex-row md:items-center md:justify-between gap-4"
                    >
                        <div>
                            <div class="flex items-center gap-2 flex-wrap">
                                <CardTitle
                                    class="text-base sm:text-lg font-black text-slate-900 flex items-center gap-2"
                                >
                                    <Package class="h-5 w-5 text-primary" />
                                    <span>Pemilihan Bahan Pangan</span>
                                </CardTitle>
                                <span
                                    class="px-2.5 py-0.5 text-xs font-extrabold rounded-md bg-amber-50 text-amber-700 border border-amber-200"
                                >
                                    Belanja Bahan Baku (PO)
                                </span>
                            </div>
                            <CardDescription
                                class="text-xs text-slate-500 mt-1"
                            >
                                Pilih bahan baku mentah dari database master
                                pangan, tentukan gramasi porsi, BDD, buffer, dan
                                estimasi biaya belanja (Food Cost).
                            </CardDescription>
                        </div>
                        <!-- <div class="flex items-center gap-2 shrink-0">
                            <Button
                                type="button"
                                @click="handleGunakanContohFormula"
                                className="bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-300 text-xs font-bold px-3.5 h-9 rounded-xl cursor-pointer flex items-center gap-1.5 shadow-2xs transition"
                                title="Muat contoh formula bahan baku untuk uji coba cepat"
                            >
                                <Sparkles class="h-4 w-4 text-amber-600" />
                                <span>Gunakan Contoh</span>
                            </Button>
                        </div> -->
                        <button
                            type="button"
                            @click="handleGunakanContohFormula"
                            class="text-[10.5px] font-bold text-primary hover:underline flex items-center gap-1 cursor-pointer shrink-0 truncate max-w-[150px]"
                            title="Gunakan Contoh"
                        >
                            <Sparkles class="h-3 w-3 shrink-0 text-amber-500" />
                            <span class="truncate"
                                >Gunakan Contoh</span
                            >
                        </button>
                    </div>
                </CardHeader>
                <CardContent class="p-4 sm:p-6 space-y-6">
                    <!-- Panduan / Rumus Kebutuhan Bahan Mentah (Toggleable) -->
                    <div
                        class="rounded-xl border border-slate-200 bg-white p-3 sm:p-3.5 text-xs space-y-2.5 shadow-2xs"
                    >
                        <div class="flex flex-col md:flex-row md:items-center justify-between gap-2.5">
                            <div class="flex items-center justify-between gap-2 w-full md:w-auto">
                                <span
                                    class="font-bold text-slate-800 flex items-center gap-1.5 text-xs"
                                >
                                    <HelpCircle class="h-4 w-4 text-primary shrink-0" />
                                    <span>Panduan Rumus Perhitungan Bahan Mentah</span>
                                </span>
                                <button
                                    type="button"
                                    @click="showRumusBahan = !showRumusBahan"
                                    class="text-[11px] text-primary font-bold hover:underline cursor-pointer shrink-0 md:hidden"
                                >
                                    {{
                                        showRumusBahan
                                            ? "Sembunyikan"
                                            : "Lihat Rumus"
                                    }}
                                </button>
                            </div>
                            <div class="flex flex-col sm:flex-row sm:items-center gap-2 w-full md:w-auto">
                                <div
                                    class="flex items-center justify-between sm:justify-start gap-1.5 text-[11px] text-slate-500 font-medium"
                                >
                                    <div class="flex items-center gap-1.5">
                                        <span class="font-bold text-slate-600">Database:</span>
                                        <span
                                            v-if="selectedBahanList.length > 0"
                                            class="text-[10px] text-amber-700 bg-amber-50 px-1.5 py-0.5 rounded border border-amber-200 font-bold inline-flex items-center gap-1"
                                            title="Database terkunci karena sudah ada bahan dipilih"
                                        >
                                            🔒 Terkunci
                                        </span>
                                    </div>
                                </div>
                                <div
                                    class="flex items-center gap-1 overflow-x-auto no-scrollbar pb-0.5 p-0.5 rounded-lg bg-slate-100 border border-slate-200/80 w-full sm:w-auto"
                                    :title="
                                        selectedBahanList.length > 0
                                            ? 'Database terkunci karena sudah ada bahan pangan yang dipilih. Hapus/reset semua bahan terlebih dahulu jika ingin mengganti database.'
                                            : 'Pilih Database Acuan'
                                    "
                                >
                                    <button
                                        type="button"
                                        @click="
                                            selectedBahanList.length ===
                                                0 &&
                                            emit('update-source', 'fta')
                                        "
                                        :disabled="
                                            selectedBahanList.length > 0
                                        "
                                        class="px-2.5 py-1 rounded-md text-[10px] font-bold transition-all shrink-0"
                                        :class="[
                                            selectedSource === 'fta'
                                                ? 'bg-white text-primary shadow-xs font-black'
                                                : 'text-slate-600 hover:text-slate-900',
                                            selectedBahanList.length > 0
                                                ? 'opacity-80 cursor-not-allowed'
                                                : 'cursor-pointer',
                                        ]"
                                    >
                                        NutriSurvey (indo.fta)
                                    </button>
                                    <button
                                        type="button"
                                        @click="
                                            selectedBahanList.length ===
                                                0 &&
                                            emit('update-source', 'csv')
                                        "
                                        :disabled="
                                            selectedBahanList.length > 0
                                        "
                                        class="px-2.5 py-1 rounded-md text-[10px] font-bold transition-all shrink-0"
                                        :class="[
                                            selectedSource === 'csv'
                                                ? 'bg-white text-primary shadow-xs font-black'
                                                : 'text-slate-600 hover:text-slate-900',
                                            selectedBahanList.length > 0
                                                ? 'opacity-80 cursor-not-allowed'
                                                : 'cursor-pointer',
                                        ]"
                                    >
                                        Kemenkes (tkpi2020.csv)
                                    </button>
                                    <button
                                        type="button"
                                        @click="
                                            selectedBahanList.length ===
                                                0 &&
                                            emit(
                                                'update-source',
                                                'tkpi2020',
                                            )
                                        "
                                        :disabled="
                                            selectedBahanList.length > 0
                                        "
                                        class="px-2.5 py-1 rounded-md text-[10px] font-bold transition-all shrink-0"
                                        :class="[
                                            selectedSource === 'tkpi2020' ||
                                            selectedSource === 'xlsx'
                                                ? 'bg-white text-primary shadow-xs font-black'
                                                : 'text-slate-600 hover:text-slate-900',
                                            selectedBahanList.length > 0
                                                ? 'opacity-80 cursor-not-allowed'
                                                : 'cursor-pointer',
                                        ]"
                                    >
                                        Modifikasi (tkpi2020.xlsx)
                                    </button>
                                    <button
                                        type="button"
                                        @click="
                                            selectedBahanList.length ===
                                                0 &&
                                            emit(
                                                'update-source',
                                                'fatsecret',
                                            )
                                        "
                                        :disabled="
                                            selectedBahanList.length > 0
                                        "
                                        class="px-2.5 py-1 rounded-md text-[10px] font-bold transition-all shrink-0"
                                        :class="[
                                            selectedSource === 'fatsecret'
                                                ? 'bg-white text-primary shadow-xs font-black'
                                                : 'text-slate-600 hover:text-slate-900',
                                            selectedBahanList.length > 0
                                                ? 'opacity-80 cursor-not-allowed'
                                                : 'cursor-pointer',
                                        ]"
                                    >
                                        FatSecret (fatsecret.com)
                                    </button>
                                </div>
                                <button
                                    type="button"
                                    @click="showRumusBahan = !showRumusBahan"
                                    class="text-[11px] text-primary font-bold hover:underline cursor-pointer shrink-0 hidden md:inline-block ml-1"
                                >
                                    {{
                                        showRumusBahan
                                            ? "Sembunyikan Rumus"
                                            : "Tampilkan Rumus"
                                    }}
                                </button>
                            </div>
                        </div>
                        <div
                            v-if="showRumusBahan"
                            class="grid grid-cols-1 md:grid-cols-3 gap-2.5 pt-2 border-t border-slate-200 text-[11px] text-slate-600"
                        >
                            <div
                                class="p-2.5 bg-white rounded-lg border border-amber-200 space-y-1"
                            >
                                <strong
                                    class="text-slate-900 font-bold block flex items-center gap-1.5"
                                    ><span
                                        class="w-2 h-2 rounded-full bg-amber-500 inline-block"
                                    ></span
                                    >1. Berat Bersih (Net):</strong
                                >
                                <code
                                    class="block font-mono text-[10.5px] bg-slate-50 p-1 rounded border border-slate-200 text-slate-800"
                                    >(Gram Bersih × Target PM) ÷ 1.000</code
                                >
                                <span
                                    class="text-[10px] text-slate-500 block leading-tight"
                                    >Khusus bahan baku pangan. Operasional diisi
                                    sesuai kebutuhan unit.</span
                                >
                            </div>
                            <div
                                class="p-2.5 bg-white rounded-lg border border-blue-200 space-y-1"
                            >
                                <strong
                                    class="text-slate-900 font-bold block flex items-center gap-1.5"
                                    ><span
                                        class="w-2 h-2 rounded-full bg-blue-500 inline-block"
                                    ></span
                                    >2. Pengadaan PO (Gross):</strong
                                >
                                <code
                                    class="block font-mono text-[10.5px] bg-blue-50/50 p-1 rounded border border-blue-200 text-slate-800"
                                    >[Net ÷ (BDD%/100)] × (1 + Buffer%)</code
                                >
                                <span
                                    class="text-[10px] text-slate-500 block leading-tight"
                                    >Faktor BDD% & Buffer% (Bahan Baku &
                                    Kebutuhan Operasional).</span
                                >
                            </div>
                            <div
                                class="p-2.5 bg-white rounded-lg border border-emerald-200 space-y-1"
                            >
                                <strong
                                    class="text-slate-900 font-bold block flex items-center gap-1.5"
                                    ><span
                                        class="w-2 h-2 rounded-full bg-emerald-500 inline-block"
                                    ></span
                                    >3. Estimasi Anggaran PO:</strong
                                >
                                <code
                                    class="block font-mono text-[10.5px] bg-emerald-50/50 p-1 rounded border border-emerald-200 text-slate-800"
                                    >Gross × Harga Satuan (Rp)</code
                                >
                                <span
                                    class="text-[10px] text-slate-500 block leading-tight"
                                    >Total anggaran pengadaan PO (Bahan Baku +
                                    Operasional).</span
                                >
                            </div>
                        </div>
                    </div>


                    <!-- ========================================================================= -->
                    <!-- BLOK-BLOK SUB MENU & VARIAN PENGGANTI ALERGI (LANGKAH 2) -->
                    <!-- ========================================================================= -->
                    <div class="space-y-6">
                        <div
                            v-for="(block, bIdx) in step2SubMenuBlocks"
                            :key="block.id"
                            :id="'card-block-' + block.id"
                            class="border rounded-2xl bg-white shadow-xs transition-all duration-200"
                            :class="[
                                block.borderCard,
                                activeComboboxBlockId === block.id
                                    ? 'relative z-30'
                                    : 'relative z-10',
                            ]"
                        >
                            <!-- Header Blok Sub Menu -->
                            <div
                                class="p-4 border-b border-slate-200 flex flex-col md:flex-row md:items-center md:justify-between gap-3 rounded-t-2xl"
                                :class="block.bgHeader"
                            >
                                <div class="flex items-center gap-3 flex-wrap">
                                    <div
                                        class="h-7 w-7 rounded-xl flex items-center justify-center font-black text-xs text-white shadow-2xs shrink-0"
                                        :class="
                                            block.isAlergi
                                                ? 'bg-rose-600'
                                                : 'bg-slate-800'
                                        "
                                    >
                                        {{
                                            block.isAlergi
                                                ? "🛡️"
                                                : block.subIndex
                                        }}
                                    </div>
                                    <div>
                                        <div
                                            class="flex items-center gap-2 flex-wrap"
                                        >
                                            <span
                                                class="text-xs font-black uppercase tracking-wider text-slate-800"
                                            >
                                                {{ block.subLabel }}:
                                            </span>
                                            <span
                                                class="text-sm font-extrabold"
                                                :class="
                                                    block.isAlergi
                                                        ? 'text-rose-900'
                                                        : 'text-slate-900'
                                                "
                                            >
                                                "{{ block.namaMenu }}"
                                            </span>
                                            <span
                                                v-if="block.isAlergi"
                                                class="px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-100 text-rose-800 border border-rose-300 shadow-2xs"
                                            >
                                                ⚠️ Varian Alergi:
                                                {{ block.jenisAlergi }}
                                            </span>
                                        </div>
                                        <!-- Info Sasaran Porsi -->
                                        <div
                                            class="text-[11px] text-slate-600 flex items-center gap-2 mt-0.5 flex-wrap"
                                        >
                                            <span
                                                v-if="!block.isAlergi"
                                                class="font-medium"
                                            >
                                                Target Porsi Normal:
                                                <strong class="text-slate-900"
                                                    >{{ totalPM }} PM</strong
                                                >
                                                (PK: {{ totalPK }}, PB:
                                                {{ totalPB }})
                                            </span>
                                            <span
                                                v-else
                                                class="font-bold text-rose-800 flex items-center gap-1"
                                            >
                                                <span
                                                    >Target Alergi
                                                    {{
                                                        block.jenisAlergi
                                                    }}:</span
                                                >
                                                <strong class="text-rose-950"
                                                    >{{
                                                        findAlergiDetail(
                                                            block.jenisAlergi,
                                                        )?.total || 0
                                                    }}
                                                    PM</strong
                                                >
                                                <span
                                                    >(PK:
                                                    {{
                                                        findAlergiDetail(
                                                            block.jenisAlergi,
                                                        )?.porsi_kecil || 0
                                                    }}, PB:
                                                    {{
                                                        findAlergiDetail(
                                                            block.jenisAlergi,
                                                        )?.porsi_besar || 0
                                                    }})</span
                                                >
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                <!-- Ringkasan Blok & Tombol Cek Rekap Pojok Kanan -->
                                <div
                                    class="flex items-center gap-2 text-xs flex-wrap self-start md:self-auto"
                                >
                                    <!-- Tombol Cek Rekapitulasi -->
                                    <button
                                        type="button"
                                        @click="scrollToRekapitulasi"
                                        class="px-2.5 py-1 rounded-lg bg-indigo-50 text-indigo-700 hover:bg-indigo-100 hover:text-indigo-900 border border-indigo-200 text-[11px] font-extrabold flex items-center gap-1.5 transition-all cursor-pointer shadow-2xs active:scale-95"
                                        title="Lihat Tabel Rekapitulasi Semua Bahan Pangan"
                                    >
                                        <ClipboardList
                                            class="h-3.5 w-3.5 text-indigo-600"
                                        />
                                        <span>Cek Rekap</span>
                                    </button>
                                    <span
                                        class="px-2.5 py-1 rounded-lg bg-white/90 border border-slate-200 text-slate-700 font-bold text-[11px] shadow-2xs"
                                    >
                                        {{ getBlockSummary(block.id).count }}
                                        Bahan
                                    </span>
                                    <div
                                        class="flex items-center gap-1 flex-wrap"
                                    >
                                        <span
                                            v-for="(
                                                grp, gIdx
                                            ) in getBlockSummary(block.id)
                                                .groupedList"
                                            :key="gIdx"
                                            class="px-2 py-0.5 rounded-lg bg-white border border-slate-200 text-slate-800 font-black text-[11px] shadow-2xs"
                                        >
                                            {{ grp.label }}
                                        </span>
                                    </div>
                                    <span
                                        class="px-2.5 py-1 rounded-lg bg-white border border-slate-200 text-slate-800 font-black text-[11px] shadow-2xs"
                                    >
                                        {{
                                            formatRupiah(
                                                getBlockSummary(block.id)
                                                    .totalCostMaster,
                                            )
                                        }}
                                    </span>
                                </div>
                            </div>

                            <!-- Selector Combobox Tambah Bahan Baku Khusus Blok Ini (Di Atas Tabel) -->
                            <div
                                class="p-3.5 bg-white border-b border-slate-200 relative z-30"
                            >
                                <div class="relative" @click.stop>
                                    <div
                                        @click="
                                            toggleComboboxForBlock(block.id)
                                        "
                                        class="w-full min-h-[42px] px-3.5 py-1.5 rounded-xl border border-slate-300 bg-white hover:border-primary/70 focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/20 transition-all flex items-center justify-between gap-3 cursor-pointer shadow-2xs"
                                    >
                                        <div
                                            class="flex items-center gap-2.5 min-w-0 flex-1"
                                        >
                                            <div
                                                class="h-6 w-6 rounded-lg bg-primary/10 text-primary flex items-center justify-center shrink-0"
                                            >
                                                <Plus class="h-3.5 w-3.5" />
                                            </div>
                                            <span
                                                class="text-xs text-slate-500 font-normal truncate"
                                            >
                                                Ketik nama bahan baku mentah
                                                untuk ditambahkan ke
                                                <strong
                                                    >{{ block.subLabel }} ({{
                                                        block.namaMenu
                                                    }})</strong
                                                >...
                                            </span>
                                        </div>
                                        <ChevronDown
                                            class="h-4 w-4 text-slate-400 shrink-0 transition-transform duration-150"
                                            :class="{
                                                'rotate-180 text-primary':
                                                    activeComboboxBlockId ===
                                                    block.id,
                                            }"
                                        />
                                    </div>

                                    <!-- Dropdown Panel Pencarian Bahan Pangan Master (Tidak Terpotong Tabel) -->
                                    <div
                                        v-if="
                                            activeComboboxBlockId === block.id
                                        "
                                        class="absolute z-50 left-0 right-0 top-full mt-1.5 bg-white rounded-2xl border border-slate-200 shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-150"
                                    >
                                        <div
                                            class="p-2.5 border-b border-slate-100 bg-slate-50/95 space-y-2.5"
                                        >
                                            <div class="relative">
                                                <Search
                                                    class="h-3.5 w-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2"
                                                />
                                                <input
                                                    type="text"
                                                    :value="
                                                        getSearchQueryForBlock(
                                                            block.id,
                                                        )
                                                    "
                                                    @input="
                                                        setSearchQueryForBlock(
                                                            block.id,
                                                            $event.target.value,
                                                        )
                                                    "
                                                    :placeholder="`Cari dari seluruh database bahan pangan untuk ${block.namaMenu}...`"
                                                    class="w-full pl-8 pr-3 py-1.5 text-xs bg-white rounded-lg border border-slate-200 focus:outline-hidden focus:border-primary font-medium"
                                                    autofocus
                                                />
                                            </div>
                                            <div
                                                class="flex items-center justify-between gap-2 text-[10px] text-slate-500 font-medium px-1 flex-wrap"
                                            >
                                                <div
                                                    class="flex items-center gap-1.5 text-xs text-slate-500 font-semibold"
                                                >
                                                    <span
                                                        class="text-primary font-bold"
                                                    >
                                                        {{
                                                            getFilteredTkpiListForBlock(
                                                                block.id,
                                                            ).length
                                                        }}
                                                        Bahan Tersedia
                                                    </span>
                                                </div>

                                                <button
                                                    type="button"
                                                    @click="
                                                        openManualBahanModal(
                                                            block,
                                                        )
                                                    "
                                                    class="inline-flex items-center justify-center h-7 w-7 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 shadow-2xs transition-colors cursor-pointer"
                                                    title="Tambah Bahan Baku Manual"
                                                >
                                                    <Plus
                                                        class="h-4 w-4 stroke-[2.5]"
                                                    />
                                                </button>
                                            </div>
                                        </div>
                                        <div
                                            class="max-h-80 overflow-y-auto divide-y divide-slate-100"
                                        >
                                            <div
                                                v-for="item in getFilteredTkpiListForBlock(
                                                    block.id,
                                                )"
                                                :key="item.id || item.code"
                                                @click="
                                                    selectTkpiItemForBlock(
                                                        item,
                                                        block,
                                                    )
                                                "
                                                class="p-3 hover:bg-primary/5 cursor-pointer transition-colors flex items-center justify-between gap-3 text-xs"
                                            >
                                                <div class="min-w-0">
                                                    <div
                                                        class="font-bold text-slate-800 truncate"
                                                    >
                                                        {{ item.nama }}
                                                    </div>
                                                    <div
                                                        class="text-[10.5px] text-slate-500 flex items-center gap-2 mt-0.5"
                                                    >
                                                        <span>{{
                                                            item.kategori
                                                        }}</span>
                                                        <span>•</span>
                                                        <span
                                                            >BDD:
                                                            {{
                                                                item.bdd || 100
                                                            }}%</span
                                                        >
                                                    </div>
                                                </div>
                                                <Button
                                                    type="button"
                                                    size="sm"
                                                    className="bg-primary/10 text-primary hover:bg-primary hover:text-white h-7 px-2.5 text-[11px] font-bold rounded-lg shrink-0"
                                                >
                                                    Pilih ke
                                                    {{ block.subLabel }}
                                                </Button>
                                            </div>
                                            <div
                                                v-if="
                                                    getFilteredTkpiListForBlock(
                                                        block.id,
                                                    ).length === 0
                                                "
                                                class="p-6 text-center text-xs text-slate-500 space-y-2.5 bg-white"
                                            >
                                                <p
                                                    class="font-medium text-slate-600"
                                                >
                                                    Bahan pangan "<span
                                                        class="font-bold text-slate-800"
                                                        >{{
                                                            getSearchQueryForBlock(
                                                                block.id,
                                                            )
                                                        }}</span
                                                    >" tidak ditemukan di
                                                    database.
                                                </p>
                                                <div>
                                                    <button
                                                        type="button"
                                                        @click="
                                                            openManualBahanModal(
                                                                block,
                                                            )
                                                        "
                                                        class="inline-flex items-center gap-1.5 px-3.5 py-1.5 text-xs font-bold rounded-xl bg-emerald-600 text-white hover:bg-emerald-700 shadow-sm transition-all cursor-pointer"
                                                    >
                                                        <Plus
                                                            class="h-3.5 w-3.5 stroke-[2.5]"
                                                        />
                                                        <span
                                                            >Tambah "{{
                                                                getSearchQueryForBlock(
                                                                    block.id,
                                                                ) ||
                                                                "Bahan Baru"
                                                            }}" Secara
                                                            Manual</span
                                                        >
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <!-- Tabel Bahan Baku Mentah Khusus Blok Ini -->
                            <div class="overflow-x-auto">
                                <table
                                    class="w-full min-w-[1100px] text-left text-xs border-collapse"
                                >
                                    <thead>
                                        <tr
                                            class="bg-white border-b border-slate-200 text-[11px] font-bold text-slate-700 uppercase tracking-wider select-none"
                                        >
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-center w-10 border-r border-slate-200/80"
                                            >
                                                No
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 min-w-[170px] w-auto border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Bahan Pangan (Master)
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 min-w-[180px] border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Nama di PO
                                                <span
                                                    class="text-rose-500 font-black"
                                                    >*</span
                                                >
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 min-w-[95px] text-center border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Satuan
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 min-w-[125px] text-center border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Jenis
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 min-w-[210px] text-center border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Peruntukan Porsi
                                            </th>
                                            <th
                                                colspan="2"
                                                class="p-2 text-center bg-white text-slate-800 border-r border-slate-200/80 font-black"
                                            >
                                                Berat Bersih (g)
                                            </th>
                                            <th
                                                colspan="2"
                                                class="p-2 text-center bg-white text-slate-800 border-r border-slate-200/80 font-black"
                                            >
                                                Berat Kotor (g)
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-center min-w-[65px] border-r border-slate-200/80"
                                            >
                                                BDD (%)
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-center min-w-[70px] border-r border-slate-200/80"
                                            >
                                                Buffer (%)
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-right bg-white text-slate-800 min-w-[95px] border-r border-slate-200/80 font-black"
                                            >
                                                Kebutuhan (PO)
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-right min-w-[115px] border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Harga / Satuan
                                                <span
                                                    class="text-rose-500 font-black"
                                                    >*</span
                                                >
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-right min-w-[95px] border-r border-slate-200/80"
                                            >
                                                Subtotal
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2.5 text-left min-w-[150px] border-r border-slate-200/80 whitespace-normal break-words leading-tight"
                                            >
                                                Keterangan
                                                <span
                                                    class="text-rose-500 font-black"
                                                    >*</span
                                                >
                                            </th>
                                            <th
                                                rowspan="2"
                                                class="p-2 text-center w-14 min-w-[56px] max-w-[56px] shrink-0"
                                            >
                                                Aksi
                                            </th>
                                        </tr>
                                        <tr
                                            class="bg-white border-b border-slate-200 text-[10px] font-bold text-slate-700 uppercase tracking-wider select-none"
                                        >
                                            <th
                                                class="p-1.5 text-center bg-white text-slate-800 border-r border-slate-200/60 min-w-[80px]"
                                            >
                                                PK
                                            </th>
                                            <th
                                                class="p-1.5 text-center bg-white text-slate-800 border-r border-slate-200/80 min-w-[80px]"
                                            >
                                                PB
                                            </th>
                                            <th
                                                class="p-1.5 text-center bg-white text-slate-800 border-r border-slate-200/60 min-w-[75px]"
                                            >
                                                PK
                                            </th>
                                            <th
                                                class="p-1.5 text-center bg-white text-slate-800 border-r border-slate-200/80 min-w-[75px]"
                                            >
                                                PB
                                            </th>
                                        </tr>
                                    </thead>
                                    <tbody
                                        class="divide-y divide-slate-100 text-slate-800"
                                    >
                                        <tr
                                            v-if="
                                                getBahanForBlock(block.id)
                                                    .length === 0
                                            "
                                        >
                                            <td
                                                colspan="16"
                                                class="p-6 text-center text-slate-400 font-medium bg-slate-50/30"
                                            >
                                                <div
                                                    class="flex flex-col items-center justify-center gap-1"
                                                >
                                                    <Package
                                                        class="h-6 w-6 text-slate-300 stroke-[1.5]"
                                                    />
                                                    <span
                                                        >Belum ada bahan baku
                                                        pangan untuk
                                                        <strong>{{
                                                            block.namaMenu
                                                        }}</strong
                                                        >.</span
                                                    >
                                                    <span
                                                        class="text-[11px] text-slate-400"
                                                        >Gunakan kolom pencarian
                                                        di atas untuk
                                                        menambahkan bahan baku
                                                        mentah.</span
                                                    >
                                                </div>
                                            </td>
                                        </tr>
                                        <tr
                                            v-for="(
                                                it, itemIdx
                                            ) in getBahanForBlock(block.id)"
                                            :key="it.originalIndex"
                                            :id="
                                                'row-bahan-' + it.originalIndex
                                            "
                                            class="hover:bg-white transition-colors"
                                        >
                                            <td
                                                class="p-3 text-center font-bold text-slate-400 align-top pt-4 border-r border-slate-100"
                                            >
                                                {{ itemIdx + 1 }}
                                            </td>
                                            <!-- 1. Bahan Pangan (Master) - Wrap & Break Words -->
                                            <td
                                                class="p-3 font-bold text-slate-900 align-top pt-4 border-r border-slate-100 min-w-[170px] whitespace-normal break-words leading-snug"
                                            >
                                                <div
                                                    class="whitespace-normal break-words flex items-center gap-1.5 flex-wrap"
                                                >
                                                    <span>{{ it.nama }}</span>
                                                    <span
                                                        v-if="
                                                            it.is_custom ||
                                                            (typeof it.code ===
                                                                'string' &&
                                                                it.code.startsWith(
                                                                    'custom_',
                                                                )) ||
                                                            (typeof it.id ===
                                                                'string' &&
                                                                it.id.startsWith(
                                                                    'custom_',
                                                                ))
                                                        "
                                                        class="inline-flex items-center px-1.5 py-0.5 rounded text-[9.5px] font-bold bg-amber-100 text-slate-700 border border-amber-300 shadow-2xs"
                                                        title="Bahan Ditambahkan Secara Manual"
                                                    >
                                                        ✍️ Manual
                                                    </span>
                                                </div>
                                                <span
                                                    v-if="it.alergen"
                                                    class="block text-[9.5px] text-amber-700 font-normal mt-0.5 whitespace-normal break-words"
                                                >
                                                    Alergen: {{ it.alergen }}
                                                </span>
                                            </td>
                                            <!-- 2. Nama di PO (Wajib diisi & Wrap) -->
                                            <td
                                                class="p-3 align-top pt-3 border-r border-slate-100 min-w-[180px]"
                                            >
                                                <textarea
                                                    rows="2"
                                                    v-model="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ].nama_po
                                                    "
                                                    placeholder="Nama di PO (Wajib diisi)..."
                                                    :class="[
                                                        'w-full px-2.5 py-1.5 text-xs border rounded-lg focus:outline-hidden font-medium transition-colors resize-y min-h-[42px] leading-snug break-words',
                                                        validationErrors[
                                                            'nama_po_' +
                                                                it.originalIndex
                                                        ] ||
                                                        validationErrors[
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_nama_po'
                                                        ]
                                                            ? 'border-rose-400 focus:border-rose-500 bg-white text-rose-900 placeholder:text-rose-400'
                                                            : !selectedBahanList[
                                                                    it
                                                                        .originalIndex
                                                                ].nama_po
                                                              ? 'border-amber-300 focus:border-amber-400 bg-white text-slate-800 placeholder:text-amber-600/70'
                                                              : 'border-slate-200 focus:border-primary text-slate-900',
                                                    ]"
                                                    @input="
                                                        clearError(
                                                            'nama_po_' +
                                                                it.originalIndex,
                                                        );
                                                        clearError(
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_nama_po',
                                                        );
                                                    "
                                                ></textarea>
                                                <p
                                                    v-if="
                                                        validationErrors[
                                                            'nama_po_' +
                                                                it.originalIndex
                                                        ] ||
                                                        validationErrors[
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_nama_po'
                                                        ]
                                                    "
                                                    class="text-[10px] text-rose-600 mt-1 font-bold flex items-center gap-1 whitespace-normal break-words leading-tight"
                                                >
                                                    <span>⚠️</span>
                                                    <span>{{
                                                        validationErrors[
                                                            "nama_po_" +
                                                                it.originalIndex
                                                        ] ||
                                                        validationErrors[
                                                            "bahan_" +
                                                                it.originalIndex +
                                                                "_nama_po"
                                                        ]
                                                    }}</span>
                                                </p>
                                                <p
                                                    v-else-if="
                                                        !selectedBahanList[
                                                            it.originalIndex
                                                        ].nama_po
                                                    "
                                                    class="text-[9.5px] text-amber-700 mt-1 font-semibold flex items-center gap-1 whitespace-normal break-words leading-tight"
                                                >
                                                    <span>⚠️</span>
                                                    <span
                                                        >Wajib diisi untuk
                                                        PO</span
                                                    >
                                                </p>
                                            </td>
                                            <!-- 2.B Satuan Pangan (Kg, Liter, Pcs, Bks, dll) -->
                                            <td
                                                class="p-3 align-top pt-3 border-r border-slate-100 min-w-[95px] text-center"
                                            >
                                                <select
                                                    v-if="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ]
                                                    "
                                                    v-model="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ].satuan
                                                    "
                                                    @change="
                                                        handleRowSatuanChange(
                                                            it.originalIndex,
                                                            $event.target.value,
                                                            it.satuan,
                                                        )
                                                    "
                                                    class="w-full px-2 py-1.5 text-xs bg-white border border-slate-200 rounded-lg focus:outline-hidden focus:border-primary font-bold text-slate-800 text-center cursor-pointer shadow-2xs hover:border-slate-300"
                                                >
                                                    <option
                                                        v-for="s in SATUAN_LIST"
                                                        :key="s.value"
                                                        :value="s.value"
                                                    >
                                                        {{ s.value }}
                                                    </option>
                                                </select>
                                            </td>
                                            <!-- 2.C Jenis Item (Bahan Baku / Operasional) -->
                                            <td
                                                class="p-3 align-top pt-3 border-r border-slate-100 min-w-[125px] text-center"
                                            >
                                                <select
                                                    :value="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ]?.jenis || 'bahan_baku'
                                                    "
                                                    @change="
                                                        handleRowJenisChange(
                                                            it.originalIndex,
                                                            $event.target.value,
                                                        )
                                                    "
                                                    :class="[
                                                        'w-full px-2 py-1.5 text-xs font-bold rounded-lg border focus:outline-hidden transition cursor-pointer shadow-2xs text-center appearance-none [background-image:none]',
                                                        (selectedBahanList[
                                                            it.originalIndex
                                                        ]?.jenis ||
                                                            'bahan_baku') ===
                                                        'operasional'
                                                            ? 'bg-amber-50 text-amber-800 border-amber-300 focus:border-amber-500'
                                                            : 'bg-emerald-50 text-emerald-800 border-emerald-300 focus:border-emerald-500',
                                                    ]"
                                                >
                                                    <option value="bahan_baku">
                                                        Bahan Baku
                                                    </option>
                                                    <option value="operasional">
                                                        Operasional
                                                    </option>
                                                </select>
                                                <span
                                                    class="block text-[9px] font-bold mt-1"
                                                    :class="
                                                        (selectedBahanList[
                                                            it.originalIndex
                                                        ]?.jenis ||
                                                            'bahan_baku') ===
                                                        'operasional'
                                                            ? 'text-amber-700'
                                                            : 'text-emerald-700'
                                                    "
                                                >
                                                    {{
                                                        (selectedBahanList[
                                                            it.originalIndex
                                                        ]?.jenis ||
                                                            "bahan_baku") ===
                                                        "operasional"
                                                            ? "Non-Gizi & Cost"
                                                            : "Gizi & Food Cost"
                                                    }}
                                                </span>
                                            </td>
                                            <!-- 3. Peruntukan Porsi (Wrap & Full Display) -->
                                            <td
                                                class="p-3 align-top pt-3 border-r border-slate-100 min-w-[210px]"
                                            >
                                                <select
                                                    :value="
                                                        getPeruntukanPorsiValue(
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ],
                                                        )
                                                    "
                                                    @change="
                                                        handlePeruntukanPorsiChange(
                                                            it.originalIndex,
                                                            $event.target.value,
                                                        )
                                                    "
                                                    class="w-full px-2 py-1.5 text-xs border rounded-lg focus:outline-hidden focus:border-primary font-bold transition-colors cursor-pointer whitespace-normal break-words"
                                                    :class="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ]?.tipe_porsi ===
                                                        'alergi'
                                                            ? 'bg-rose-50 text-rose-900 border-rose-300'
                                                            : 'bg-white text-slate-800 border-slate-200'
                                                    "
                                                >
                                                    <option value="normal">
                                                        ✓ Porsi Normal (Standar)
                                                    </option>
                                                    <optgroup
                                                        v-if="
                                                            availableAlergiPmOptions.length >
                                                            0
                                                        "
                                                        label="Porsi Varian Khusus Alergi"
                                                    >
                                                        <option
                                                            v-for="opt in availableAlergiPmOptions"
                                                            :key="
                                                                opt.jenis_alergi
                                                            "
                                                            :value="`alergi:${opt.jenis_alergi}`"
                                                        >
                                                            ⚠️ Alergi:
                                                            {{
                                                                opt.jenis_alergi
                                                            }}
                                                            ({{ opt.total }}
                                                            Porsi • PK:
                                                            {{ opt.pk }}, PB:
                                                            {{ opt.pb }})
                                                        </option>
                                                    </optgroup>
                                                </select>
                                            </td>
                                            <!-- 4. Berat/Takaran Bersih - PK -->
                                            <td
                                                class="p-2.5 align-top pt-3 text-center bg-white border-r border-slate-100"
                                            >
                                                <div
                                                    class="flex items-center justify-center gap-1"
                                                >
                                                    <input
                                                        type="number"
                                                        min="0"
                                                        step="0.1"
                                                        v-model.number="
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ].gram_pk
                                                        "
                                                        @keydown="
                                                            handleDecimalKeydown
                                                        "
                                                        placeholder="0"
                                                        :class="[
                                                            'w-16 text-center px-1.5 py-1 text-xs font-bold border rounded-lg focus:outline-hidden mx-auto transition-colors',
                                                            validationErrors[
                                                                'bahan_' +
                                                                    it.originalIndex +
                                                                    '_gram'
                                                            ]
                                                                ? 'border-rose-400 bg-white text-rose-900'
                                                                : (Number(
                                                                        selectedBahanList[
                                                                            it
                                                                                .originalIndex
                                                                        ]
                                                                            .gram_pk,
                                                                    ) || 0) <=
                                                                        0 &&
                                                                    (Number(
                                                                        selectedBahanList[
                                                                            it
                                                                                .originalIndex
                                                                        ]
                                                                            .gram_pb,
                                                                    ) || 0) <= 0
                                                                  ? 'border-amber-300 bg-white'
                                                                  : 'border-slate-200 focus:border-primary',
                                                        ]"
                                                        @input="
                                                            handleGramPkInput(
                                                                it.originalIndex,
                                                            )
                                                        "
                                                        @change="
                                                            handleGramPkInput(
                                                                it.originalIndex,
                                                            )
                                                        "
                                                    />
                                                    <span
                                                        class="text-[10px] font-bold text-slate-500 shrink-0"
                                                    >
                                                        {{
                                                            getPortionUnit(
                                                                selectedBahanList[
                                                                    it
                                                                        .originalIndex
                                                                ].satuan,
                                                            )
                                                        }}
                                                    </span>
                                                </div>
                                                <div
                                                    class="text-[9.5px] text-slate-500 font-medium mt-1 whitespace-nowrap bg-slate-50 py-0.5 rounded border border-slate-100"
                                                >
                                                    ×
                                                    {{ it.targetPKCount }} porsi
                                                </div>
                                                <p
                                                    v-if="
                                                        validationErrors[
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_gram'
                                                        ]
                                                    "
                                                    class="text-[9px] text-rose-600 font-bold mt-1 leading-tight whitespace-normal break-words"
                                                >
                                                    {{
                                                        validationErrors[
                                                            "bahan_" +
                                                                it.originalIndex +
                                                                "_gram"
                                                        ]
                                                    }}
                                                </p>
                                            </td>
                                            <!-- 5. Berat/Takaran Bersih - PB -->
                                            <td
                                                class="p-2.5 align-top pt-3 text-center bg-white border-r border-slate-100"
                                            >
                                                <div
                                                    class="flex items-center justify-center gap-1"
                                                >
                                                    <input
                                                        type="number"
                                                        min="0"
                                                        step="0.1"
                                                        v-model.number="
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ].gram_pb
                                                        "
                                                        @keydown="
                                                            handleDecimalKeydown
                                                        "
                                                        placeholder="0"
                                                        :class="[
                                                            'w-16 text-center px-1.5 py-1 text-xs font-bold border rounded-lg focus:outline-hidden mx-auto transition-colors',
                                                            validationErrors[
                                                                'bahan_' +
                                                                    it.originalIndex +
                                                                    '_gram'
                                                            ]
                                                                ? 'border-rose-400 bg-white text-rose-900'
                                                                : (Number(
                                                                        selectedBahanList[
                                                                            it
                                                                                .originalIndex
                                                                        ]
                                                                            .gram_pk,
                                                                    ) || 0) <=
                                                                        0 &&
                                                                    (Number(
                                                                        selectedBahanList[
                                                                            it
                                                                                .originalIndex
                                                                        ]
                                                                            .gram_pb,
                                                                    ) || 0) <= 0
                                                                  ? 'border-amber-300 bg-white'
                                                                  : 'border-slate-200 focus:border-primary',
                                                        ]"
                                                        @input="
                                                            handleGramPbInput(
                                                                it.originalIndex,
                                                            )
                                                        "
                                                        @change="
                                                            handleGramPbInput(
                                                                it.originalIndex,
                                                            )
                                                        "
                                                    />
                                                    <span
                                                        class="text-[10px] font-bold text-slate-500 shrink-0"
                                                    >
                                                        {{
                                                            getPortionUnit(
                                                                selectedBahanList[
                                                                    it
                                                                        .originalIndex
                                                                ].satuan,
                                                            )
                                                        }}
                                                    </span>
                                                </div>
                                                <div
                                                    class="text-[9.5px] text-slate-500 font-medium mt-1 whitespace-nowrap bg-slate-50 py-0.5 rounded border border-slate-100"
                                                >
                                                    ×
                                                    {{ it.targetPBCount }} porsi
                                                </div>
                                            </td>
                                            <!-- 6. Berat/Takaran Kotor - PK -->
                                            <td
                                                class="p-2.5 align-top pt-3.5 text-center bg-white border-r border-slate-100 font-bold text-slate-900"
                                            >
                                                <div>
                                                    {{
                                                        formatPortionValue(
                                                            it.grossGramPK,
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ].satuan,
                                                        )
                                                    }}
                                                </div>
                                                <div
                                                    class="text-[9.5px] text-slate-400 font-normal mt-0.5"
                                                >
                                                    (Net ÷ {{ it.bdd || 100 }}%)
                                                </div>
                                            </td>
                                            <!-- 7. Berat/Takaran Kotor - PB -->
                                            <td
                                                class="p-2.5 align-top pt-3.5 text-center bg-white border-r border-slate-100 font-bold text-slate-900"
                                            >
                                                <div>
                                                    {{
                                                        formatPortionValue(
                                                            it.grossGramPB,
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ].satuan,
                                                        )
                                                    }}
                                                </div>
                                                <div
                                                    class="text-[9.5px] text-slate-400 font-normal mt-0.5"
                                                >
                                                    (Net ÷ {{ it.bdd || 100 }}%)
                                                </div>
                                            </td>
                                            <!-- 8. BDD (%) -->
                                            <td
                                                class="p-3 text-center align-top pt-4 text-slate-700 font-medium border-r border-slate-100"
                                            >
                                                {{ it.bdd || 100 }}%
                                            </td>
                                            <!-- 9. Buffer (%) -->
                                            <td
                                                class="p-3 align-top pt-3 border-r border-slate-100"
                                            >
                                                <input
                                                    type="number"
                                                    min="0"
                                                    step="0.1"
                                                    v-model.number="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ].buffer
                                                    "
                                                    @keydown="
                                                        handleDecimalKeydown
                                                    "
                                                    @input="
                                                        handleBufferInput(
                                                            it.originalIndex,
                                                        )
                                                    "
                                                    @change="
                                                        handleBufferInput(
                                                            it.originalIndex,
                                                        )
                                                    "
                                                    class="w-14 text-center px-1.5 py-1 text-xs border border-slate-200 rounded-lg focus:outline-hidden focus:border-primary mx-auto"
                                                />
                                            </td>
                                            <!-- 10. Kebutuhan (Sesuai Satuan) -->
                                            <td
                                                class="p-3 text-right font-bold text-slate-900 bg-white align-top pt-4 whitespace-nowrap border-r border-slate-100"
                                            >
                                                {{
                                                    formatGrossQty(
                                                        it.totalGrossKg,
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ].satuan,
                                                    )
                                                }}
                                            </td>
                                            <!-- 11. Harga / Satuan (Wajib diisi > 0) -->
                                            <td
                                                class="p-3 align-top pt-3 border-r border-slate-100 min-w-[115px]"
                                            >
                                                <input
                                                    type="text"
                                                    inputmode="numeric"
                                                    :placeholder="`Rp 0 / ${selectedBahanList[it.originalIndex]?.satuan || 'Kg'} *`"
                                                    :value="
                                                        formatHargaInput(
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ]?.harga_master,
                                                        )
                                                    "
                                                    @input="
                                                        handleHargaMasterInput(
                                                            it.originalIndex,
                                                            $event,
                                                        );
                                                        clearError(
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_harga',
                                                        );
                                                    "
                                                    :class="[
                                                        'w-28 text-right px-2 py-1 text-xs border rounded-lg focus:outline-hidden font-medium transition-colors',
                                                        validationErrors[
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_harga'
                                                        ]
                                                            ? 'border-rose-400 bg-white text-rose-900 font-bold'
                                                            : !selectedBahanList[
                                                                    it
                                                                        .originalIndex
                                                                ]
                                                                    ?.harga_master ||
                                                                Number(
                                                                    selectedBahanList[
                                                                        it
                                                                            .originalIndex
                                                                    ]
                                                                        ?.harga_master,
                                                                ) <= 0
                                                              ? 'border-amber-300 bg-white text-slate-800'
                                                              : 'border-slate-200 focus:border-primary text-slate-800',
                                                    ]"
                                                />
                                                <div
                                                    class="text-[9.5px] text-slate-500 font-medium mt-0.5 text-right"
                                                >
                                                    per
                                                    {{
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ]?.satuan || "Kg"
                                                    }}
                                                </div>
                                                <p
                                                    v-if="
                                                        validationErrors[
                                                            'bahan_' +
                                                                it.originalIndex +
                                                                '_harga'
                                                        ]
                                                    "
                                                    class="text-[9.5px] text-rose-600 font-bold mt-1 leading-tight whitespace-normal break-words"
                                                >
                                                    {{
                                                        validationErrors[
                                                            "bahan_" +
                                                                it.originalIndex +
                                                                "_harga"
                                                        ]
                                                    }}
                                                </p>
                                                <p
                                                    v-else-if="
                                                        !selectedBahanList[
                                                            it.originalIndex
                                                        ]?.harga_master ||
                                                        Number(
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ]?.harga_master,
                                                        ) <= 0
                                                    "
                                                    class="text-[9px] text-amber-700 font-semibold mt-1 leading-tight whitespace-normal break-words"
                                                >
                                                    ⚠️ Harga wajib diisi > 0
                                                </p>
                                            </td>
                                            <!-- 12. Subtotal -->
                                            <td
                                                class="p-3 text-right font-bold text-slate-900 align-top pt-4 whitespace-nowrap border-r border-slate-100"
                                            >
                                                {{
                                                    formatRupiah(
                                                        it.subtotalMaster,
                                                    )
                                                }}
                                            </td>
                                            <!-- 13. Keterangan (Catatan Tambahan) -->
                                            <td
                                                class="p-2.5 align-top pt-3 border-r border-slate-100 min-w-[150px]"
                                            >
                                                <textarea
                                                    rows="2"
                                                    v-model="
                                                        selectedBahanList[
                                                            it.originalIndex
                                                        ].keterangan
                                                    "
                                                    @blur="
                                                        if (
                                                            !selectedBahanList[
                                                                it.originalIndex
                                                            ]?.keterangan ||
                                                            !selectedBahanList[
                                                                it.originalIndex
                                                            ]?.keterangan.trim()
                                                        ) {
                                                            selectedBahanList[
                                                                it.originalIndex
                                                            ].keterangan = '-';
                                                        }
                                                    "
                                                    placeholder="Wajib diisi atau '-'..."
                                                    class="w-full px-2 py-1.5 text-xs border border-slate-200 rounded-lg focus:outline-hidden focus:border-primary text-slate-800 placeholder:text-slate-400 font-medium resize-y min-h-[42px] leading-snug break-words"
                                                ></textarea>
                                            </td>
                                            <!-- 14. Aksi -->
                                            <td
                                                class="p-2 text-center align-middle w-14 min-w-[56px] max-w-[56px] shrink-0"
                                            >
                                                <button
                                                    type="button"
                                                    @click="
                                                        handleRemoveBahan(
                                                            it.originalIndex,
                                                        )
                                                    "
                                                    class="p-1.5 text-rose-500 hover:text-rose-700 hover:bg-rose-50 rounded-lg transition-colors cursor-pointer inline-flex items-center justify-center mx-auto"
                                                    title="Hapus Bahan dari Sub Menu"
                                                >
                                                    <Trash2 class="h-4 w-4" />
                                                </button>
                                            </td>
                                        </tr>
                                    </tbody>
                                    <tfoot
                                        v-if="
                                            getBahanForBlock(block.id).length >
                                            0
                                        "
                                        class="bg-white font-bold border-t border-slate-200 text-xs"
                                    >
                                        <tr>
                                            <td
                                                colspan="12"
                                                class="p-2.5 text-right uppercase text-[10.5px] text-slate-600 font-extrabold border-r border-slate-200/80"
                                            >
                                                Total Kebutuhan
                                                {{ block.subLabel }}:
                                            </td>
                                            <td
                                                class="p-2.5 text-right font-black text-blue-950 bg-blue-100/30 whitespace-nowrap border-r border-slate-200/80 align-middle"
                                            >
                                                <div
                                                    class="flex flex-col items-end justify-center gap-1"
                                                >
                                                    <div
                                                        v-for="(
                                                            grp, gIdx
                                                        ) in getBlockSummary(
                                                            block.id,
                                                        ).groupedList"
                                                        :key="gIdx"
                                                        class="inline-flex items-center px-2 py-0.5 rounded-md bg-white border border-blue-200 text-blue-950 text-xs font-black shadow-2xs"
                                                    >
                                                        <span>{{
                                                            grp.label
                                                        }}</span>
                                                    </div>
                                                </div>
                                            </td>
                                            <td
                                                class="border-r border-slate-200/80"
                                            ></td>
                                            <td
                                                class="p-2.5 text-right font-black text-emerald-900 whitespace-nowrap border-r border-slate-200/80"
                                            >
                                                {{
                                                    formatRupiah(
                                                        getBlockSummary(
                                                            block.id,
                                                        ).totalCostMaster,
                                                    )
                                                }}
                                            </td>
                                            <td
                                                class="border-r border-slate-200/80 min-w-[150px]"
                                            ></td>
                                            <td
                                                class="w-14 min-w-[56px] max-w-[56px]"
                                            ></td>
                                        </tr>
                                    </tfoot>
                                </table>
                            </div>
                        </div>
                    </div>

                    <!-- ========================================================================= -->
                    <!-- TABEL REKAPITULASI SEMUA BAHAN PANGAN DARI SELURUH SUB MENU (READ-ONLY) -->
                    <!-- ========================================================================= -->
                    <div
                        id="tabel-rekapitulasi-bahan-pangan"
                        class="border border-indigo-200 rounded-2xl overflow-hidden bg-white shadow-xs scroll-mt-20"
                    >
                        <div
                            class="p-4 bg-gradient-to-r from-indigo-50/90 via-slate-50 to-indigo-50/60 border-b border-indigo-100 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3"
                        >
                            <div class="flex items-center gap-3">
                                <div
                                    class="h-8 w-8 rounded-xl bg-indigo-600 text-white flex items-center justify-center shadow-xs shrink-0"
                                >
                                    <ClipboardList class="h-4.5 w-4.5" />
                                </div>
                                <div>
                                    <div
                                        class="flex items-center gap-2 flex-wrap"
                                    >
                                        <h4
                                            class="text-sm font-black text-slate-900 tracking-tight"
                                        >
                                            Rekapitulasi Semua Bahan Pangan (PO
                                            Belanja)
                                        </h4>
                                        <span
                                            class="px-2 py-0.5 text-[10px] font-extrabold rounded-md bg-indigo-100 text-indigo-800 border border-indigo-200 shadow-2xs"
                                        >
                                            Mode Tinjauan (Read-Only)
                                        </span>
                                    </div>
                                    <p
                                        class="text-[11px] text-slate-500 mt-0.5"
                                    >
                                        Daftar gabungan seluruh bahan baku
                                        mentah dari masing-masing Sub Menu dan
                                        varian pengganti alergi.
                                    </p>
                                </div>
                            </div>
                            <div class="flex items-center gap-2 shrink-0">
                                <span
                                    class="px-3 py-1 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-700 shadow-2xs"
                                >
                                    Total:
                                    <strong class="text-indigo-600">{{
                                        bahanCalculations.length
                                    }}</strong>
                                    Bahan Baku Mentah
                                </span>
                            </div>
                        </div>

                        <!-- Tabel Rekapitulasi Read-Only -->
                        <div class="overflow-x-auto">
                            <table
                                class="w-full min-w-[1200px] text-left text-xs border-collapse"
                            >
                                <thead>
                                    <tr
                                        class="bg-white border-b border-slate-200 text-[11px] font-bold text-slate-700 uppercase tracking-wider select-none"
                                    >
                                        <th
                                            rowspan="2"
                                            class="p-2.5 text-center w-10 border-r border-slate-200/80"
                                        >
                                            No
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 min-w-[160px] border-r border-slate-200/80"
                                        >
                                            Sub Menu
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 min-w-[160px] border-r border-slate-200/80"
                                        >
                                            Bahan Pangan
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 min-w-[130px] border-r border-slate-200/80"
                                        >
                                            Nama di PO
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 min-w-[70px] text-center border-r border-slate-200/80"
                                        >
                                            Satuan
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 min-w-[150px] text-center border-r border-slate-200/80"
                                        >
                                            Peruntukan Porsi
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 min-w-[85px] border-r border-slate-200/80"
                                        >
                                            Kategori
                                        </th>
                                        <th
                                            colspan="2"
                                            class="p-2 text-center bg-white text-slate-800 border-r border-slate-200/80 font-black"
                                        >
                                            Berat Bersih (g)
                                        </th>
                                        <th
                                            colspan="2"
                                            class="p-2 text-center bg-white text-slate-800 border-r border-slate-200/80 font-black"
                                        >
                                            Berat Kotor (g)
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 text-center min-w-[65px] border-r border-slate-200/80"
                                        >
                                            BDD (%)
                                        </th>
                                        <th
                                            rowspan="2"
                                            class="p-2.5 text-center min-w-[70px] border-r border-slate-200/80"
