                                                                !hasUnassignedBahan('persiapan')
                                                                    ? 'bg-slate-200 text-slate-500 opacity-60 cursor-not-allowed border border-slate-300'
                                                                    : 'bg-amber-600 hover:bg-amber-700 text-white cursor-pointer'
